let currentLang = localStorage.getItem('climoLang') || 'en';

function t(key){
  const dict = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
  return dict[key] || TRANSLATIONS.en[key] || key;
}
window.t = t;

function applyLanguage(code){
  if(!TRANSLATIONS[code]) code = 'en';
  currentLang = code;
  localStorage.setItem('climoLang', code);

  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    el.textContent = t(key);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    el.placeholder = t(key);
  });

  const langMeta = LANGUAGES.find(l => l.code === code) || LANGUAGES[0];
  const labelEl = document.getElementById('langBtnLabel');
  if(labelEl) labelEl.textContent = langMeta.native;

  document.querySelectorAll('.lang-item').forEach(el => {
    el.classList.toggle('active', el.getAttribute('data-code') === code);
  });

  document.documentElement.setAttribute('lang', code === 'en' ? 'en' : code);
}

function buildLangMenu(){
  const menu = document.getElementById('langMenu');
  if(!menu) return;
  menu.innerHTML = LANGUAGES.map(l =>
    `<div class="lang-item${l.code===currentLang?' active':''}" data-code="${l.code}">
       <span class="li-native">${l.native}</span><span class="li-english">${l.english}</span>
     </div>`
  ).join('');
  menu.querySelectorAll('.lang-item').forEach(item => {
    item.addEventListener('click', () => {
      applyLanguage(item.getAttribute('data-code'));
      menu.classList.remove('show');
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  buildLangMenu();
  applyLanguage(currentLang);

  const langBtn = document.getElementById('langBtn');
  const langMenu = document.getElementById('langMenu');
  langBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    langMenu.classList.toggle('show');
  });
  document.addEventListener('click', (e) => {
    if(!document.getElementById('langWrap').contains(e.target)){
      langMenu.classList.remove('show');
    }
  });
});
// ===================== End Language / i18n =====================

