  function fallbackStateValue(name,param){
    const f=FALLBACK_STATE_VALUES[normalizeStateName(name)];
    if(f && Number.isFinite(f[param])) return f[param];
    // Geometry-based deterministic fallback for any unmatched state/UT.
    const item=weatherAreaLayers.find(x=>normalizeStateName(x.name)===normalizeStateName(name));
    const lat=item?.center?.lat ?? 22;
    const lon=item?.center?.lng ?? 79;
    if(param==='temperature') return Math.max(10,Math.min(38,31-(Math.abs(lat-20)*0.55)+(Math.sin(lon*0.4)*1.2)));
    if(param==='humidity') return Math.max(35,Math.min(90,78-Math.abs(lat-20)*1.1+(Math.cos(lon)*3)));
    if(param==='wind') return Math.max(5,Math.min(35,14+Math.abs(lon-78)*0.35+(Math.cos(lat)*4)));
    return Math.max(0.5,Math.min(18,7-Math.abs(lat-20)*0.18+(Math.sin(lon)*2.5)));
  }
  function getStateValue(item,param){
    // Single source of truth: live Open-Meteo forecast for the state (realistic, matches panel).
    const live=stateLiveWeather.get(normalizeStateName(item.name));
    if(live){
      const v=param==='temperature'?live.temperature:param==='humidity'?live.humidity:param==='wind'?live.wind:live.rainfall24h;
      if(Number.isFinite(v)) return v;
    }
    // fallbacks only if live isn't available yet
    const stationAvg=stationStateAverage(item.name,param);
    if(Number.isFinite(stationAvg)) return stationAvg;
    return fallbackStateValue(item.name,param);
  }

  function updateWeatherChoropleth(){
    if(!weatherChoroplethLayer||!activeChoroplethParam) return;
    const cfg=CHOROPLETHS[activeChoroplethParam];
    setAtmosphere(activeChoroplethParam);
    weatherAreaLayers.forEach(item=>{
      const v=getStateValue(item,activeChoroplethParam);
      const ok=Number.isFinite(v);
      item.value=v;
      item.layer.setStyle({fillColor:ok?interpolateColor(v,cfg.stops):'#465066',fillOpacity:ok?.72:.12});
    });
  }

  function addWeatherLegend(){
    removeWeatherLegend();
    const cfg=CHOROPLETHS[activeChoroplethParam];
    weatherLegendControl=L.control({position:'bottomright'});
    weatherLegendControl.onAdd=function(){
      const div=L.DomUtil.create('div','state-weather-legend');
      const gradient=cfg.stops.map(x=>`${x[1]} ${((x[0]-cfg.min)/(cfg.max-cfg.min))*100}%`).join(',');
      div.innerHTML=`<div class="state-weather-legend-title">${cfg.title} · INDIA STATE / UT</div><div class="state-weather-gradient" style="background:linear-gradient(90deg,${gradient})"></div><div class="state-weather-ticks"><span>${cfg.format(cfg.stops[0][0])}</span><span>${cfg.format(cfg.stops[Math.floor(cfg.stops.length/2)][0])}</span><span>${cfg.format(cfg.stops[cfg.stops.length-1][0])}</span></div><div class="state-weather-source">STATE AVERAGE • ATMOSPHERIC OVERLAY</div>`;
      L.DomEvent.disableClickPropagation(div); return div;
    };
    weatherLegendControl.addTo(map);
  }
  function removeWeatherLegend(){if(weatherLegendControl){map.removeControl(weatherLegendControl);weatherLegendControl=null;}}
  function showStateDetail(name){
    const panel=document.getElementById('stateDetailPanel');
    const live=stateLiveWeather.get(normalizeStateName(name));
    const cfgKey=activeChoroplethParam||'temperature';
    const titles={temperature:'Average Temperature',rainfall:'Rainfall (24h)',humidity:'Average Humidity',wind:'Average Wind Speed'};
    const units={temperature:'°C',rainfall:'mm',humidity:'%',wind:'km/h'};
    // Use the SAME value source as the choropleth colour + tooltip, so they always match.
    const areaItem = weatherAreaLayers.find(x=>normalizeStateName(x.name)===normalizeStateName(name));
    let mainVal='—', badge='';
    const mv = areaItem ? getStateValue(areaItem, cfgKey) : (live ? (cfgKey==='temperature'?live.temperature:cfgKey==='humidity'?live.humidity:cfgKey==='wind'?live.wind:live.rainfall24h) : NaN);
    if(Number.isFinite(mv)){
      mainVal = Math.round(mv*10)/10;
      if(cfgKey==='temperature'){
        badge = mv>=38?'<span class="sd-bdg hot">High</span>':mv<=16?'<span class="sd-bdg cool">Cool</span>':'<span class="sd-bdg mod">Moderate</span>';
      }
    }
    // secondary cells: prefer live grid; fall back to the same getStateValue per-parameter
    const feelsV = live&&Number.isFinite(live.feels)?live.feels:NaN;
    const tminV = live&&Number.isFinite(live.tmin)?live.tmin:NaN;
    const tmaxV = live&&Number.isFinite(live.tmax)?live.tmax:NaN;
    const humV = areaItem?getStateValue(areaItem,'humidity'):(live?live.humidity:NaN);
    const windV = areaItem?getStateValue(areaItem,'wind'):(live?live.wind:NaN);
    const dirs=['N','NE','E','SE','S','SW','W','NW'];
    const wdir = live&&Number.isFinite(live.windDir)?dirs[Math.round(live.windDir/45)%8]:'';
    const now=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});
    panel.className='state-detail show';
    panel.innerHTML=`
      <div class="sd-head"><div class="sd-state">${name}</div><button class="sd-close" id="sdClose">✕</button></div>
      <div class="sd-metric">${titles[cfgKey]}</div>
      <div class="sd-big" style="color:#7CFF9B">${mainVal}<span>${units[cfgKey]}</span> ${badge}</div>
      <div class="sd-live"><span class="d"></span>Live · State Average · ${now}</div>
      <div class="sd-grid">
        <div class="sd-cell"><div class="sd-cl">Feels Like</div><div class="sd-cv">${Number.isFinite(feelsV)?Math.round(feelsV)+'°C':'—'}</div></div>
        <div class="sd-cell"><div class="sd-cl">Min / Max</div><div class="sd-cv">${Number.isFinite(tminV)?Math.round(tminV):'—'}° / ${Number.isFinite(tmaxV)?Math.round(tmaxV):'—'}°</div></div>
        <div class="sd-cell"><div class="sd-cl">Humidity</div><div class="sd-cv">${Number.isFinite(humV)?Math.round(humV)+'%':'—'}</div></div>
        <div class="sd-cell"><div class="sd-cl">Wind</div><div class="sd-cv">${Number.isFinite(windV)?Math.round(windV)+' km/h '+wdir:'—'}</div></div>
      </div>`;
    document.getElementById('sdClose').onclick=()=>panel.classList.remove('show');
  }

  function hideWeatherChoropleth(){
    if(weatherChoroplethLayer && map.hasLayer(weatherChoroplethLayer)) map.removeLayer(weatherChoroplethLayer);
    removeWeatherLegend(); activeChoroplethParam=null; setAtmosphere('none');
    if(window.__indiaMask && map.hasLayer(window.__indiaMask)) map.removeLayer(window.__indiaMask);
    if(document.getElementById('toggleStations')?.classList.contains('on')) map.addLayer(stationLayer);
  }
  async function showWeatherChoropleth(param){
    activeChoroplethParam=param;
    setAtmosphere(param);
    if(weatherChoroplethLayer){
      map.addLayer(weatherChoroplethLayer);
      if(window.__indiaMask){ window.__indiaMask.addTo(map); if(weatherChoroplethLayer.bringToFront) weatherChoroplethLayer.bringToFront(); }
      updateWeatherChoropleth();
      addWeatherLegend();
      if(!stateWeatherPromise){
        stateWeatherPromise=Promise.race([
          fetchLiveStateWeather(),
          new Promise((_,reject)=>setTimeout(()=>reject(new Error('Live state weather timeout')),5000))
        ]).then(()=>{
          updateWeatherChoropleth();
        }).catch(err=>{
          console.warn('Live state weather unavailable; keeping fallback choropleth:',err);
          updateWeatherChoropleth();
        });
      }
      return;
    }
    let loadingNote=document.getElementById('choroplethLoading');
    if(!loadingNote){
      loadingNote=document.createElement('div');
      loadingNote.id='choroplethLoading';
      loadingNote.className='state-weather-loading';
      document.getElementById('map').appendChild(loadingNote);
    }
    loadingNote.style.display='block';
    loadingNote.textContent='Drawing India State / UT choropleth…';
    try{
      if(!weatherGeoJSONPromise){
        weatherGeoJSONPromise=fetch(STATE_GEOJSON_URL,{mode:'cors',cache:'force-cache'}).then(r=>{
          if(!r.ok) throw new Error(`State boundary download failed (${r.status})`);
          return r.json();
        });
      }
      const geo=await Promise.race([
        weatherGeoJSONPromise,
        new Promise((_,reject)=>setTimeout(()=>reject(new Error('State boundary timeout')),6000))
      ]);
      if(!geo||geo.type!=='FeatureCollection'||!Array.isArray(geo.features)||!geo.features.length) throw new Error('Invalid state boundary dataset');
      weatherAreaLayers=[];
      weatherChoroplethLayer=L.geoJSON(geo,{
        style:{color:'#d9f7ff',weight:1.05,opacity:.82,fillColor:'#465066',fillOpacity:.52},
        onEachFeature:(feature,layer)=>{
          const name=getStateName(feature), center=layer.getBounds().getCenter();
          const item={name,center,layer,value:NaN};
          weatherAreaLayers.push(item);
          // Keep the map completely clean: no permanent labels, no on-map popup.
          // State name + weather appear ONLY in the side detail panel after a click,
          // so there is a single source of truth and nothing to mismatch.
          layer.on({
            mouseover:e=>e.target.setStyle({weight:2.5,color:'#ffffff',fillOpacity:.68}),
            mouseout:e=>{e.target.setStyle({weight:1.05,color:'#d9f7ff'});updateWeatherChoropleth();},
            click:e=>{ showStateDetail(name); }
          });
        }
      }).addTo(map);

      // ===== Dark mask: black out everything EXCEPT India (India stays highlighted) =====
      try{
        if(window.__indiaMask){ map.removeLayer(window.__indiaMask); window.__indiaMask=null; }
        const holes=[];
        geo.features.forEach(f=>{
          const g=f.geometry;
          if(!g) return;
          if(g.type==='Polygon') g.coordinates.forEach(ring=>holes.push(ring.map(([lng,lat])=>[lat,lng])));
          else if(g.type==='MultiPolygon') g.coordinates.forEach(poly=>poly.forEach(ring=>holes.push(ring.map(([lng,lat])=>[lat,lng]))));
        });
        window.__indiaMask=L.polygon([ [[-85,-359],[-85,359],[85,359],[85,-359]], ...holes ],
          {stroke:false, fillColor:'#01030a', fillOpacity:0.86, interactive:false, className:'india-dark-mask'});
        // only show the mask while a weather layer is active
        if(activeChoroplethParam){ window.__indiaMask.addTo(map); window.__indiaMask.bringToFront?.(); if(weatherChoroplethLayer.bringToFront) weatherChoroplethLayer.bringToFront(); }
      }catch(maskErr){ /* mask is cosmetic; ignore failures */ }

      // The choropleth is a background layer; stations must never disappear when
      // Temperature / Rainfall / Humidity / Wind is selected.
      if(!map.hasLayer(stationLayer) && document.getElementById('toggleStations')?.classList.contains('on')) stationLayer.addTo(map);

      // IMPORTANT: render a coloured choropleth immediately, even with no internet/API.
      updateWeatherChoropleth();
      addWeatherLegend();
      loadingNote.textContent='Loading live data… fallback colours are active';

      stateWeatherPromise=Promise.race([
        fetchLiveStateWeather(),
        new Promise((_,reject)=>setTimeout(()=>reject(new Error('Live state weather timeout')),5000))
      ]);
      try{
        await stateWeatherPromise;
      }catch(err){
        console.warn('Live state API unavailable; fallback choropleth retained:',err);
      }
      updateWeatherChoropleth();
      loadingNote.style.display='none';
    }catch(err){
      console.error('State weather choropleth:',err);
      // If boundaries themselves fail, do not trap the user on a loading screen.
      // Restore the normal map and explain the issue briefly.
      loadingNote.textContent='State boundary unavailable — normal map restored.';
      setTimeout(()=>{loadingNote.style.display='none';},2200);
    }
  }

  const stationLayer = L.markerClusterGroup({
    showCoverageOnHover:false,
    spiderfyOnMaxZoom:true,
    maxClusterRadius:55,
    iconCreateFunction: function(cluster){
      const count = cluster.getChildCount();
      // Color the cluster by the highest risk score among its child stations
      let maxScore = 0;
      cluster.getAllChildMarkers().forEach(m => {
        if(m.stationRef && (m.stationRef._liveScore ?? m.stationRef.risk?.score ?? 0) > maxScore){
          maxScore = m.stationRef._liveScore ?? m.stationRef.risk?.score ?? 0;
        }
      });
      const color = riskColor(maxScore);
      const size = count < 10 ? 36 : count < 25 ? 44 : 52;
      return L.divIcon({
        html:`<div style="
          width:${size}px;height:${size}px;border-radius:50%;
          background:rgba(15,22,40,0.92);border:2px solid ${color};
          box-shadow:0 0 12px ${color}66;
          display:flex;align-items:center;justify-content:center;
          font-family:'JetBrains Mono',monospace;font-weight:600;font-size:13px;color:${color};
        ">${count}</div>`,
        className:'', iconSize:[size,size]
      });
    }
  }); // NOT added to the map here — visibility is controlled entirely by the
      // "Stations" sidebar toggle (see wireToggle('rowStations', ...) below),
      // which starts OFF, so station points stay hidden until the user turns it on.
  const riskLayer = L.layerGroup().addTo(map);
  const bufferLayer = L.layerGroup(); // Buffer Analysis Layer — off by default, added to map via its sidebar toggle
  const markers = {};

  const weatherLayerSelect = document.getElementById('weatherLayerSelect');
