  document.getElementById('rowBaseOsm').onclick = () => switchBaseMap(osmStandardLayer, 'radioOsm');
  document.getElementById('rowBaseSat').onclick = () => switchBaseMap(satelliteLayer, 'radioSat');

  function typeIconSvg(type, color){
    const shapes = {
      AWS: `<circle cx="12" cy="12" r="5" fill="${color}"/><g stroke="${color}" stroke-width="1.6"><line x1="12" y1="1" x2="12" y2="4"/><line x1="12" y1="20" x2="12" y2="23"/><line x1="1" y1="12" x2="4" y2="12"/><line x1="20" y1="12" x2="23" y2="12"/></g>`,
      rain_gauge: `<path d="M12 2 C12 2 6 11 6 15 a6 6 0 0 0 12 0 C18 11 12 2 12 2 Z" fill="${color}"/>`,
      radar: `<polygon points="12,2 22,20 2,20" fill="${color}"/>`,
      river_gauge: `<path d="M2 12 q3 -5 6 0 t6 0 t6 0" stroke="${color}" stroke-width="2.4" fill="none"/><path d="M2 17 q3 -5 6 0 t6 0 t6 0" stroke="${color}" stroke-width="2.4" fill="none" opacity="0.55"/>`
    };
    return `<svg width="24" height="24" viewBox="0 0 24 24">${shapes[type]}</svg>`;
  }

  function makeIcon(station){
    const color = TYPE_COLOR[station.type];
    return L.divIcon({
      className:'',
      html:`<div style="width:30px;height:30px;border-radius:8px;background:rgba(15,22,40,0.9);border:1.5px solid ${color};display:flex;align-items:center;justify-content:center;box-shadow:0 0 10px ${color}55;">${typeIconSvg(station.type,color)}</div>`,
      iconSize:[30,30], iconAnchor:[15,15]
    });
  }

  // WMO weather codes -> short label + emoji icon (used for current conditions + the forecast strip)
  const WMO = {
    0:["Clear sky","☀️"], 1:["Mainly clear","🌤️"], 2:["Partly cloudy","⛅"], 3:["Overcast","☁️"],
    45:["Fog","🌫️"], 48:["Rime fog","🌫️"],
    51:["Light drizzle","🌦️"], 53:["Drizzle","🌦️"], 55:["Dense drizzle","🌦️"],
    61:["Light rain","🌧️"], 63:["Rain","🌧️"], 65:["Heavy rain","🌧️"],
    66:["Freezing rain","🌧️"], 67:["Heavy freezing rain","🌧️"],
    71:["Light snow","🌨️"], 73:["Snow","🌨️"], 75:["Heavy snow","🌨️"], 77:["Snow grains","🌨️"],
    80:["Light showers","🌦️"], 81:["Showers","🌦️"], 82:["Violent showers","⛈️"],
    85:["Snow showers","🌨️"], 86:["Heavy snow showers","🌨️"],
    95:["Thunderstorm","⛈️"], 96:["Thunderstorm + hail","⛈️"], 99:["Severe thunderstorm","⛈️"]
  };
  function wmoInfo(code){ return WMO[code] || ["—","🌡️"]; }

  function haversineKm(lat1, lon1, lat2, lon2){
    const R = 6371, toRad = d => d * Math.PI / 180;
    const dLat = toRad(lat2 - lat1), dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
    return R * 2 * Math.asin(Math.sqrt(a));
  }

  function findNearestStation(lat, lon, excludeId){
    let nearest = null, best = Infinity;
    INDIA_STATIONS.forEach(s => {
      if(excludeId !== undefined && s.id === excludeId) return; // don't recommend the flooded station as its own "safe point"
      const d = haversineKm(lat, lon, s.lat, s.lon);
      if(d < best){ best = d; nearest = s; }
    });
    return nearest ? {station: nearest, distanceKm: Math.round(best * 10) / 10} : null;
  }

  // ---- Extreme weather alert banner ----
  const alreadyBannered = new Set();
  let bannerQueue = [];
  let bannerShowing = false;
  let bannerTimer = null;

  function queueBanner(station, score){
    if(alreadyBannered.has(station.id)) return;
    alreadyBannered.add(station.id);
    bannerQueue.push({station, score});
    if(!bannerShowing) showNextBanner();
  }

  function showNextBanner(){
    if(bannerQueue.length === 0){ bannerShowing = false; return; }
    bannerShowing = true;
    const {station, score} = bannerQueue.shift();
    const banner = document.getElementById('alertBanner');
    const severe = score >= 66;
    banner.classList.toggle('severity-mid', !severe);
    document.getElementById('abIcon').textContent = severe ? '🚨' : '⚠️';
    document.getElementById('abTitle').textContent = severe
      ? `High flood/weather risk — ${station.name}`
      : `Elevated risk building — ${station.name}`;
    document.getElementById('abSub').textContent = `${station.state} · Risk score ${score}/100 · Tap for details`;
    banner.onclick = (e) => {
      if(e.target.id === 'abClose') return;
      map.setView([station.lat, station.lon], 9);
      openDrawer(station);
      dismissBanner();
    };
    document.getElementById('abClose').onclick = (e) => { e.stopPropagation(); dismissBanner(); };
    banner.classList.add('show');
    clearTimeout(bannerTimer);
    bannerTimer = setTimeout(dismissBanner, 6000);

    maybeNativeNotify(
      document.getElementById('abTitle').textContent,
      document.getElementById('abSub').textContent
    );
  }

  // OS-level popup (works even if the CLIMO tab is in the background or minimised) —
  // separate from the in-app banner above, which only shows while the tab is open and focused.
  function maybeNativeNotify(title, body){
    if(typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
    try{ new Notification(title, {body, tag: 'climo-alert'}); }
    catch(e){ /* some browsers block Notification from unfocused tabs — safe to ignore */ }
  }

  function dismissBanner(){
    document.getElementById('alertBanner').classList.remove('show');
    clearTimeout(bannerTimer);
    setTimeout(showNextBanner, 400);
  }

  // Multi-Source Data Resolver: Attempts IMD Endpoint & Fallbacks seamlessly to ECMWF model telemetry
  async function fetchStationData(station){
    const primaryUrl = `https://api.open-meteo.com/v1/forecast?latitude=${station.lat}&longitude=${station.lon}` +
      `&current=temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m,weathercode` +
      `&hourly=temperature_2m,precipitation,weathercode,precipitation_probability` +
      `&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max` +
      `&past_days=2&forecast_days=10&timezone=Asia%2FKolkata`;

    const res = await fetch(primaryUrl);
    if(!res.ok) throw new Error('Network error');
    const data = await res.json();
    return {
      current: data.current,
      hourlyTimes: data.hourly.time,
      hourlyTemp: data.hourly.temperature_2m,
      hourlyRain: data.hourly.precipitation,
      hourlyWeathercode: data.hourly.weathercode,
      hourlyPrecipProb: data.hourly.precipitation_probability,
      daily: data.daily
    };
  }

  /*
   * Weather-derived flood-risk index.
   * This is NOT a hydrodynamic flood model; it is an operational screening
   * index built from the live weather variables already available in this app.
   *
   * Weighting:
   *   45% trailing 24h rainfall
   *   25% trailing 6h rainfall
   *   10% current precipitation intensity
   *   15% today's precipitation probability
   *    5% thunderstorm signal
   */
  function computeRisk(hourlyRain, current = {}, daily = {}){
    const rain = Array.isArray(hourlyRain) ? hourlyRain : [];
    const recent24 = rain.slice(Math.max(0, rain.length - 24));
    const recent6  = rain.slice(Math.max(0, rain.length - 6));
    const rainfall24h = recent24.reduce((a,b) => a + (Number(b) || 0), 0);
    const rainfall6h  = recent6.reduce((a,b) => a + (Number(b) || 0), 0);

    const rain24Norm = Math.min(rainfall24h / 75, 1);
    const rain6Norm  = Math.min(rainfall6h / 35, 1);
    const currentNorm = Math.min((Number(current.precipitation) || 0) / 8, 1);

    const probRaw = Array.isArray(daily.precipitation_probability_max)
      ? Number(daily.precipitation_probability_max[0] ?? daily.precipitation_probability_max[1] ?? 0)
      : 0;
    const probabilityNorm = Math.min(probRaw / 80, 1);

    const wc = Number(current.weathercode);
    const stormNorm = [95, 96, 99].includes(wc) ? 1 : ([80,81,82].includes(wc) ? 0.5 : 0);

    const score = Math.max(0, Math.min(100, Math.round(
      rain24Norm * 45 +
      rain6Norm * 25 +
      currentNorm * 10 +
      probabilityNorm * 15 +
      stormNorm * 5
    )));

    return {
      score,
      rainfall24h: Math.round(rainfall24h * 10) / 10,
      rainfall6h: Math.round(rainfall6h * 10) / 10,
      rainProbability: probRaw,
      currentRain: Number(current.precipitation) || 0
    };
  }

  // Open-Meteo is queried with timezone=Asia/Kolkata, so every hourly/daily
  // timestamp it returns is a bare wall-clock string with NO UTC offset, e.g.
  // "2026-08-29T22:00". Handing that straight to `new Date(...)` makes the
  // browser parse it using ITS OWN local timezone instead of India's — so on
  // any machine/browser not set to IST, the "current" position on the
  // timeline silently drifts by the gap between the two zones (this is what
  // caused the clock/slider to show a time hours behind the real IST time).
  // Explicitly pinning +05:30 here makes it resolve to the correct instant
  // no matter what timezone the browser itself is running in.
  function parseIST(t){
    if(t instanceof Date) return t;
    if(typeof t !== 'string') return new Date(t);
    if(/[zZ]$|[+-]\d{2}:?\d{2}$/.test(t)) return new Date(t); // already has an offset — leave it
    return new Date(t + '+05:30');
  }

  let timelineTimes = null;
  let sliderIndex = 0;
  let playTimer = null;
  let nowIndexGlobal = null; // the timeline index that represents "right now" — alerts fire off this, not off wherever the scrubber happens to be

  function renderStation(station, data){
    const risk = computeRisk(data.hourlyRain, data.current, data.daily);
    station.data = data;
    station.risk = risk;

    const marker = L.marker([station.lat, station.lon], {icon: makeIcon(station)});
    marker.stationRef = station;
    marker.on('click', () => openDrawer(station));
    marker.addTo(stationLayer);

    // Risk circle kept as a detached (never-added-to-map) object purely so the
    // score-based setStyle/setRadius calls in updateAtTimeIndex keep working —
    // the old amber "risk circles" overlay itself has been removed from the map.
    const circle = L.circle([station.lat, station.lon], {
      radius: 20000 + risk.score * 500,
      color: riskColor(risk.score),
      weight:0, fillOpacity:0.25
    });

    markers[station.id] = {marker, circle, station};
  }

  function updateAtTimeIndex(idx){
    let anyElevated = [];
    Object.values(markers).forEach(({circle, station})=>{
      const rain = station.data.hourlyRain[idx] ?? 0;
      const temp = station.data.hourlyTemp[idx];
      const start = Math.max(0, idx-23);
      const windowSum = station.data.hourlyRain.slice(start, idx+1).reduce((a,b)=>a+(b||0),0);
      const score = Math.min(Math.round((windowSum/75)*100),100);
      circle.setStyle({color: riskColor(score), fillOpacity:0.25});
      circle.setRadius(20000 + score*500);
      station._liveScore = score;
      station._liveTemp = temp;
      station._liveRain = rain;
      if(score >= 20) anyElevated.push({station, score});
      // Popup banners are tied to the LIVE ("now") index, not the scrubber's last position —
      // previously this compared idx to slider.max, so a banner only ever fired if you dragged
      // the timeline all the way to the last forecast hour. Fixed to fire off whatever index
      // represents the current moment, which is what boot() and the periodic refresh both use.
      if(idx === nowIndexGlobal && score >= 34) queueBanner(station, score);
    });
    renderAlerts(anyElevated);
    if(stationLayer.refreshClusters) stationLayer.refreshClusters();
    if(bufferLayerOn) drawStationBuffers(bufferRadiusKm); // keep buffers in sync with live scores
    if(timelineTimes && timelineTimes[idx]){
      const d = parseIST(timelineTimes[idx]);
      document.getElementById('clockLabel').textContent = d.toLocaleString('en-IN', {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'});
    }
    if(idx === nowIndexGlobal) checkMyLocationAlert();
  }

  function renderAlerts(list){
    const el = document.getElementById('alertsList');
    el.innerHTML = "";
    if(list.length === 0){
      el.innerHTML = `<div style="font-size:12px;color:var(--text-faint);">No high risk alerts across India.</div>`;
      return;
    }
    list.sort((a,b)=> b.score - a.score).slice(0,6).forEach(({station, score})=>{
      const card = document.createElement('div');
      card.className = 'alert-card';
      card.style.borderLeftColor = riskColor(score);
      card.innerHTML = `<div class="alert-name">${station.name} (${station.state})</div>
        <div class="alert-meta"><span>${riskLabel(score)} risk</span><span>${score}/100</span></div>`;
      card.onclick = () => { map.setView([station.lat, station.lon], 9); openDrawer(station); };
      el.appendChild(card);
    });
  }

  function openDrawer(station){
    asstStation = station;   // assistant now answers about this city
    const risk = station.risk;
    const color = TYPE_COLOR[station.type];
    const rc = riskColor(station._liveScore ?? risk.score);
    const rl = riskLabel(station._liveScore ?? risk.score);

    // Compute nearest OTHER station for any real station clicked (not just the GPS 'me' entry).
    // Cached on the station object so it's only calculated once per station.
    if(!station.nearest && station.id !== 'me'){
      const found = findNearestStation(station.lat, station.lon, station.id);
      if(found) station.nearest = found;
    }

    const [wLabel, wIcon] = wmoInfo(station.data.current.weathercode);

    const crowdHtml = crowdReportHtml(station);

    let nearestHtml = '';
    if(station.nearest){
      nearestHtml = `<div class="nearest-station-row" id="nearestStationRow">
        <div>
          <div class="ns-name">Nearest official station: ${station.nearest.station.name}</div>
          <div class="ns-dist">${station.nearest.distanceKm} km away — tap to view</div>
        </div>
        <div>→</div>
      </div>`;
    }

    let hourlyHtml = '';
    if(station.data.hourlyTimes && station.data.hourlyTimes.length){
      // Same rolling-window idea as the 7-day strip below, but hourly: find the
      // hourly slot for the CURRENT clock hour (e.g. 12:35 -> the 12:00 slot,
      // not 13:00), step back one hour so the strip opens with what just
      // happened, then run "Now" and the next 24 hours from there — so this
      // always centers on "now" and slides forward every time the drawer is
      // opened (or refreshed) instead of showing a fixed clock day.
      const nowIdx = findCurrentHourIndex(station.data.hourlyTimes, new Date());
      const hStart = Math.max(0, nowIdx - 1); // include the past hour, when the data has one
      const hourSlice = station.data.hourlyTimes.slice(hStart, nowIdx + 25); // past hour + now + next 24 hours
      // The live current-conditions reading from the API (data.current) is more
      // accurate for THIS instant than the hourly forecast bucket for the current
      // hour, so the "Now" tile pulls its icon/temp from there instead of from
      // hourlyWeathercode/hourlyTemp — everything else in the strip (past hour,
      // next 24 hours) still comes from the hourly forecast, same as before.
      const nowIconInfo = wmoInfo(station.data.current.weathercode);
      const nowTemp = station._liveTemp ?? station.data.current.temperature_2m;
      hourlyHtml = `<div class="metric-label" style="margin-bottom:8px;">Past Hour · Now · Next 24 Hours <span style="color:var(--text-faint);font-weight:400;"></span></div><div class="forecast-strip">` +
        hourSlice.map((t, offset) => {
          const i = hStart + offset;
          const isNow = i === nowIdx;
          const [label, icon] = isNow ? nowIconInfo : wmoInfo(station.data.hourlyWeathercode?.[i]);
          const hourLabel = isNow
            ? 'Now'
            : parseIST(t).toLocaleTimeString('en-IN', {hour:'numeric', hour12:true}).replace(' ', '');
          const prob = station.data.hourlyPrecipProb?.[i] ?? 0;
          const temp = isNow ? nowTemp : station.data.hourlyTemp[i];
          const tileClass = isNow ? 'forecast-day fd-now' : (i < nowIdx ? 'forecast-day fd-past' : 'forecast-day');
          return `<div class="${tileClass}" title="${label}">
            <div class="fd-date">${hourLabel}</div>
            <div class="fd-icon">${icon}</div>
            <div class="fd-temp">${Math.round(temp)}°</div>
            <div class="fd-rain">${Math.round(prob)}%</div>
          </div>`;
        }).join('') + `</div>`;
    }

    let forecastHtml = '';
    if(station.data.daily && station.data.daily.time){
      const d = station.data.daily;
      // The API is called with past_days=2, so d.time includes 2 already-elapsed
      // days at the front. Find "today" (in the same Asia/Kolkata timezone the
      // API was queried with) and start the strip there, so the panel always
      // begins on the current day and rolls forward automatically — no past
      // days shown, and no manual date math needed tomorrow.
      const todayStr = new Date().toLocaleDateString('en-CA', {timeZone:'Asia/Kolkata'}); // YYYY-MM-DD
      let startIdx = d.time.indexOf(todayStr);
      if(startIdx === -1) startIdx = 0; // fallback if the exact date isn't found
      const days = d.time.slice(startIdx, startIdx + 7);
      forecastHtml = `<div class="metric-label" style="margin-bottom:8px;">7-Day Forecast <span style="color:var(--text-faint);font-weight:400;"></span></div><div class="forecast-strip">` +
        days.map((date, offset) => {
          const i = startIdx + offset;
          const [label, icon] = wmoInfo(d.weathercode[i]);
          const dayName = new Date(date).toLocaleDateString('en-IN', {weekday:'short', timeZone:'UTC'});
          return `<div class="forecast-day" title="${label}">
            <div class="fd-date">${dayName}</div>
            <div class="fd-icon">${icon}</div>
            <div class="fd-temp">${Math.round(d.temperature_2m_max[i])}° <span class="lo">${Math.round(d.temperature_2m_min[i])}°</span></div>
            <div class="fd-rain">${Math.round(d.precipitation_probability_max[i] ?? 0)}%</div>
          </div>`;
        }).join('') + `</div>`;
    }

    document.getElementById('drawerContent').innerHTML = `
      <span class="drawer-type-chip" style="border-color:${color}66;color:${color}">${station.state ? station.state + ' — ' + station.type : 'Live GPS Reading'}</span>
      <div class="drawer-name">${station.name}</div>
      <div class="drawer-code mono">${station.code}</div>
      <div class="current-conditions">
        <div class="cc-icon">${wIcon}</div>
        <div>
          <div class="cc-label">${wLabel}</div>
          <div class="cc-sub">Current conditions · Open-Meteo forecast </div>
        </div>
      </div>
      ${nearestHtml}
      ${hourlyHtml}
      ${forecastHtml}
      <div class="metric-grid">
        <div class="metric-box"><div class="metric-label">Temp</div><div class="metric-value">${(station._liveTemp ?? station.data.current.temperature_2m).toFixed(1)}°C</div></div>
        <div class="metric-box"><div class="metric-label">Humidity</div><div class="metric-value">${Math.round(station.data.current.relative_humidity_2m)}%</div></div>
        <div class="metric-box"><div class="metric-label">Rain (hr)</div><div class="metric-value">${(station._liveRain ?? station.data.current.precipitation).toFixed(1)}mm</div></div>
        <div class="metric-box"><div class="metric-label">Wind</div><div class="metric-value">${Math.round(station.data.current.wind_speed_10m)}km/h</div></div>
      </div>
      <div class="risk-block">
        <div class="risk-header">
          <span class="metric-label" style="margin:0;">Regional Flood Risk</span>
          <span class="risk-score-num" style="color:${rc}">${station._liveScore ?? risk.score}</span>
        </div>
        <div class="risk-bar-track"><div class="risk-bar-fill" style="width:${station._liveScore ?? risk.score}%;background:${rc}"></div></div>
        <div style="font-size:11.5px;color:var(--text-muted);margin-top:8px;">${rl} vulnerability level based on trailing 24h accumulated rainfall (${risk.rainfall24h}mm).</div>
      </div>
      ${crowdHtml}
    `;
    document.getElementById('drawer').classList.add('open');
    document.getElementById('climateLegend').classList.add('legend-shifted'); // keep temp/heatmap colour bar clear of the drawer
    // ---- local feedback submit ----
    const fbSend = document.getElementById('fbSend');
    if(fbSend){
      fbSend.onclick = () => {
        const type = document.getElementById('fbType').value;
        const text = document.getElementById('fbText').value.trim();
        if(!text){ document.getElementById('fbText').focus(); return; }
        const feed = document.getElementById('fbFeed');
        const time = new Date().toLocaleTimeString('en-IN', {hour:'2-digit', minute:'2-digit'});
        const item = document.createElement('div');
        item.className = 'fb-item';
        item.innerHTML = `<div class="fb-item-top"><span class="fb-tag">${type}</span><span class="fb-time">${time}</span></div><div class="fb-msg">${text.replace(/</g,'&lt;')}</div>`;
        feed.prepend(item);
        document.getElementById('fbText').value = '';
        document.getElementById('fbThanks').className = 'fb-thanks show';
        setTimeout(() => { const t = document.getElementById('fbThanks'); if(t) t.className = 'fb-thanks'; }, 2500);
      };
    }

    if(station.nearest){
      const row = document.getElementById('nearestStationRow');
      if(row){
        row.onclick = () => {
          const from = station;
          const target = station.nearest.station;
          const distKm = station.nearest.distanceKm;

          // draw the shortest route line between the two stations
          drawNearestRoute(from, target, distKm);

          const openIt = () => {
            if(target.data){ openDrawer(target); }
            else{
              fetchStationData(target).then(data => {
                target.data = data;
                target.risk = computeRisk(data.hourlyRain, data.current, data.daily);
                openDrawer(target);
              });
            }
          };
          // drawNearestRoute fits the view to the real road path; just open the drawer after
          setTimeout(openIt, 700);
        };
      }
    }
  }

  // shortest-route line between a station and its nearest neighbour
  let nearestRouteLine = null, nearestRouteMarkers = [];
  let myLocationMarker = null;
  let clickWeatherMarker = null; // temporary pin dropped wherever the user clicks the map to check weather there
  async function drawNearestRoute(from, to, distKm){
    if(nearestRouteLine){ map.removeLayer(nearestRouteLine); nearestRouteMarkers.forEach(m => map.removeLayer(m)); nearestRouteMarkers = []; }

    // start + end dots
    const a = L.circleMarker([from.lat, from.lon], {radius:6, color:'#8B7CF6', fillColor:'#8B7CF6', fillOpacity:1}).addTo(map).bindTooltip(from.name.split(' (')[0]);
    const b = L.circleMarker([to.lat, to.lon], {radius:6, color:'#4ADE80', fillColor:'#4ADE80', fillOpacity:1}).addTo(map).bindTooltip('Nearest: ' + to.name.split(' (')[0]);
    nearestRouteMarkers = [a, b];

    let usedRoad = false, roadDistKm = distKm, roadMin = null;
    // try a REAL road-network route via OpenRouteService
    if(ORS_CONFIG.apiKey && ORS_CONFIG.apiKey !== "PASTE_YOUR_OPENROUTESERVICE_KEY_HERE"){
      try{
        const res = await callORS({ coordinates: [[from.lon, from.lat],[to.lon, to.lat]] });
        if(res.ok){
          const geo = await res.json();
          const feat = geo.features && geo.features[0];
          if(feat){
            const latlngs = feat.geometry.coordinates.map(([lon,lat]) => [lat, lon]);
            nearestRouteLine = L.polyline(latlngs, {color:'#4FD9D0', weight:5, opacity:0.95}).addTo(map);
            roadDistKm = (feat.properties.summary.distance/1000).toFixed(1);
            roadMin = Math.round(feat.properties.summary.duration/60);
            usedRoad = true;
          } else {
            console.warn('ORS returned no route feature for this pair', geo);
          }
        } else {
          // Log the real reason (bad/expired key, quota exceeded, unreachable points, etc.)
          // so a fallback to the straight line is diagnosable instead of silent.
          const errBody = await res.text().catch(()=> '');
          console.warn(`ORS routing failed (HTTP ${res.status}) — falling back to straight-line estimate.`, errBody);
        }
      }catch(e){ console.warn('ORS request errored — falling back to straight-line estimate.', e); }
    }

    // fallback: straight dashed line if the road route wasn't available
    if(!usedRoad){
      nearestRouteLine = L.polyline([[from.lat, from.lon],[to.lat, to.lon]], {
        color:'#4FD9D0', weight:4, opacity:0.95, dashArray:'8 8'
      }).addTo(map);
      nearestRouteLine.bindTooltip('Road route unavailable right now — showing straight-line estimate', {sticky:true});
    }

    map.flyToBounds(nearestRouteLine.getBounds(), {padding:[90,90], duration:1.2});
  }
  document.getElementById('drawerClose').onclick = () => {
    document.getElementById('drawer').classList.remove('open');
    document.getElementById('climateLegend').classList.remove('legend-shifted');
    if(nearestRouteLine){ map.removeLayer(nearestRouteLine); nearestRouteLine = null; }
    nearestRouteMarkers.forEach(m => map.removeLayer(m));
    nearestRouteMarkers = [];
    if(myLocationMarker){ map.removeLayer(myLocationMarker); myLocationMarker = null; }
    if(clickWeatherMarker){ map.removeLayer(clickWeatherMarker); clickWeatherMarker = null; }
    map.flyTo([22.5937, 78.9629], 5, {duration:1.2});
  };

  // Toggle Controls
  function wireToggle(rowId, toggleId, layer){
    const row = document.getElementById(rowId), tg = document.getElementById(toggleId);
    row.onclick = () => {
      const on = tg.classList.toggle('on');
      if(on) map.addLayer(layer); else map.removeLayer(layer);
    };
  }
  wireToggle('rowStations','toggleStations', stationLayer);

  // "Risk Heatmap" toggle no longer shows the old amber risk circles — it now just
  // shows/hides the Temp / Humidity / Rainfall climate buttons underneath it, and
  // switches off whichever climate layer is active when you turn it off.
  document.getElementById('rowRisk').onclick = () => {
    const tg = document.getElementById('toggleRisk');
    const on = tg.classList.toggle('on');
    document.getElementById('climateControls').style.display = on ? 'block' : 'none';
    if(!on && activeClimateParam){
      turnOffClimateHeatmap(); // hides whichever heatmap (live or year-based) is currently showing
    }
  };

  /* ===================================================================
     Climate Heatmap (Temperature / Humidity / Rainfall) — TWO independent views:
       1) "Risk Heatmap" toggle + Temp/Humidity/Rainfall buttons -> LIVE view,
          drawn straight from each station's current Open-Meteo reading.
       2) Weather Time Explorer's year slider/Play button -> YEAR-BASED view,
          drawn from the India Climate Pulse dataset (WEATHER_DATA, 90 IMD
          stations, 2000\u20132030 incl. LSTM forecast), matched by Station_ID
          against INDIA_STATIONS' own id field (same WMO/IMD IDs).
     Both render as a real Leaflet.heat gradient blob layer (the same visual
     technique heatmap.html uses) onto the same single climateHeatLayer \u2014
     whichever control was touched most recently is what's shown on the map.
     Only one parameter shows at a time; clicking the active live button again
     turns it off.
     =================================================================== */

  // "Risk Heatmap" (the Temp/Humidity/Rainfall buttons) and the "Weather Time
  // Explorer" year slider are two fully independent controls now:
  //   - climateMode:'live'  -> buttons draw straight from each station's current
  //     live Open-Meteo reading (same data the markers/drawer use). No year involved.
  //   - climateMode:'year'  -> the slider/Play button draw from the 2000-2030
  //     WEATHER_DATA table for whatever year is selected. No live data involved.
  // Only one heatmap layer is ever on the map at a time — whichever control was
  // touched most recently "wins" and decides what climateHeatLayer shows.
  let climateHeatLayer = null;
  let activeClimateParam = null;
  let climateMode = null; // 'live' | 'year' | null
  let climateYear = 2000; // driven by the "2000–2030 Heatmap Forecast" slider — starts at 2000

  // Per-station data indexed by year, so the slider can show any year 2000–2030,
  // not just the latest one on record.
  const CLIMATE_BY_STATION_YEAR = {};
  (function buildClimateLookup(){
    WEATHER_DATA.forEach(row => {
      if(!CLIMATE_BY_STATION_YEAR[row.Station_ID]) CLIMATE_BY_STATION_YEAR[row.Station_ID] = {};
      CLIMATE_BY_STATION_YEAR[row.Station_ID][row.Year] = row;
    });
  })();

  const CLIMATE_GRADIENTS = {
    Temperature_C:    {0.0:'#1f5f7a', 0.5:'#ffb347', 1.0:'#d81f39'},
    Humidity_percent: {0.0:'#3a2a1a', 0.5:'#3fae9e', 1.0:'#1a7f8c'},
    Rainfall_mm:      {0.0:'#3a2a1a', 0.5:'#8fb8ff', 1.0:'#1f3fae'}
  };

  // ---- YEAR-BASED ranges/legend (2000-2030 WEATHER_DATA table) ----
  const CLIMATE_YEAR_RANGES = {
    Temperature_C:   {min:15,  max:42},
    Humidity_percent:{min:30,  max:90},
    Rainfall_mm:     {min:200, max:3200}
  };
  const CLIMATE_YEAR_LEGEND_META = {
    Temperature_C:    {title:'Temperature (°C)',    domain:[15, 28, 42],     fmt:v => Math.round(v) + '°C'},
    Humidity_percent: {title:'Relative Humidity (%)',domain:[30, 60, 90],    fmt:v => Math.round(v) + '%'},
    Rainfall_mm:       {title:'Annual Rainfall (mm)', domain:[200, 1500, 3200],fmt:v => v.toLocaleString() + ' mm'}
  };

  // ---- LIVE ranges/legend (current Open-Meteo station readings) ----
  // Rainfall here is trailing 24h accumulation (mm), not an annual total, so its
  // scale is intentionally much smaller than the year-based table's.
  const CLIMATE_LIVE_RANGES = {
    Temperature_C:   {min:15,  max:45},
    Humidity_percent:{min:20,  max:100},
    Rainfall_mm:     {min:0,   max:75}
  };
  const CLIMATE_LIVE_LEGEND_META = {
    Temperature_C:    {title:'Live Temperature (°C)',      domain:[15, 30, 45], fmt:v => Math.round(v) + '°C'},
    Humidity_percent: {title:'Live Relative Humidity (%)', domain:[20, 60, 100],fmt:v => Math.round(v) + '%'},
    Rainfall_mm:       {title:'Live 24h Rainfall (mm)',     domain:[0, 37, 75],  fmt:v => Math.round(v) + ' mm'}
  };

  const climateLegendEl      = document.getElementById('climateLegend');
  const climateLegendTitleEl = document.getElementById('climateLegendTitle');
  const climateLegendBarEl   = document.getElementById('climateLegendBar');
  const climateLegendMinEl   = document.getElementById('climateLegendMin');
  const climateLegendMidEl   = document.getElementById('climateLegendMid');
  const climateLegendMaxEl   = document.getElementById('climateLegendMax');

  function updateClimateLegend(param, mode){
    const meta = (mode === 'live' ? CLIMATE_LIVE_LEGEND_META : CLIMATE_YEAR_LEGEND_META)[param];
    const grad = CLIMATE_GRADIENTS[param];
    climateLegendTitleEl.textContent = meta.title;
    climateLegendBarEl.style.background = `linear-gradient(to right, ${grad[0.0]}, ${grad[0.5]}, ${grad[1.0]})`;
    climateLegendMinEl.textContent = meta.fmt(meta.domain[0]);
    climateLegendMidEl.textContent = meta.fmt(meta.domain[1]);
    climateLegendMaxEl.textContent = meta.fmt(meta.domain[2]);
    climateLegendEl.classList.add('visible');
  }
  function hideClimateLegend(){
    climateLegendEl.classList.remove('visible');
  }

  function highlightClimateBtn(param){
    document.querySelectorAll('.climate-btn').forEach(b => b.classList.remove('active'));
    const btnId = param === 'Temperature_C' ? 'climateBtnTemp' : param === 'Humidity_percent' ? 'climateBtnHumidity' : 'climateBtnRainfall';
    document.getElementById(btnId).classList.add('active');
  }

  // Renders the heatmap from LIVE per-station data (the same Open-Meteo readings
  // driving the markers/drawer) — this is the "Risk Heatmap" toggle's own view
  // and never looks at climateYear or the WEATHER_DATA table.
  function renderClimateHeatmapLive(param){
    if(climateHeatLayer){ map.removeLayer(climateHeatLayer); climateHeatLayer = null; }
    const range = CLIMATE_LIVE_RANGES[param];
    const points = [];
    Object.values(markers).forEach(({station}) => {
      if(!station.data || !station.data.current) return;
      let value;
      if(param === 'Temperature_C'){
        value = station._liveTemp ?? station.data.current.temperature_2m;
      } else if(param === 'Humidity_percent'){
        value = station.data.current.relative_humidity_2m;
      } else { // Rainfall_mm — trailing 24h accumulated rainfall, same metric the risk score uses
        value = station.risk ? station.risk.rainfall24h : 0;
      }
      if(typeof value !== 'number' || Number.isNaN(value)) return;
      const intensity = Math.max(0, Math.min(1, (value - range.min) / (range.max - range.min)));
      points.push([station.lat, station.lon, 0.35 + intensity * 0.65]);
    });
    climateHeatLayer = L.heatLayer(points, {
      radius: 42, blur: 32, maxZoom: 7, minOpacity: 0.25,
      gradient: CLIMATE_GRADIENTS[param]
    }).addTo(map);
  }

  // Renders the heatmap for whichever param is active, at the currently selected
  // climateYear, from the 2000-2030 WEATHER_DATA table — this is the Weather
  // Time Explorer's own view and never looks at live station readings. Called
  // whenever the year slider moves or the Play button ticks.
  function renderClimateHeatmapForYear(){
    if(!activeClimateParam) return;
    if(climateHeatLayer){ map.removeLayer(climateHeatLayer); climateHeatLayer = null; }
    const param = activeClimateParam;
    const range = CLIMATE_YEAR_RANGES[param];
    const points = [];
    INDIA_STATIONS.forEach(station => {
      const row = (CLIMATE_BY_STATION_YEAR[station.id] || {})[climateYear];
      if(!row || typeof row[param] !== 'number') return;
      const intensity = Math.max(0, Math.min(1, (row[param] - range.min) / (range.max - range.min)));
      points.push([station.lat, station.lon, 0.35 + intensity * 0.65]);
    });
    climateHeatLayer = L.heatLayer(points, {
      radius: 42, blur: 32, maxZoom: 7, minOpacity: 0.25,
      gradient: CLIMATE_GRADIENTS[param]
    }).addTo(map);
  }

  // Fully switches the climate heatmap layer + its colour-bar legend off,
  // resets the active param/mode, un-highlights the Temp/Humidity/Rainfall
  // buttons, and stops the year-slider "Play" animation if it's running.
  function turnOffClimateHeatmap(){
    if(climatePlaying) climatePause();
    activeClimateParam = null;
    climateMode = null;
    if(climateHeatLayer){ map.removeLayer(climateHeatLayer); climateHeatLayer = null; }
    hideClimateLegend();
    document.querySelectorAll('.climate-btn').forEach(b => b.classList.remove('active'));
  }

  // Temp/Humidity/Rainfall buttons under the "Risk Heatmap" toggle — always LIVE,
  // regardless of whatever the time-explorer slider is currently set to.
  function showClimateHeatmap(param){
    if(activeClimateParam === param && climateMode === 'live'){
      turnOffClimateHeatmap(); // re-clicking the active live param turns it off
      return;
    }
    activeClimateParam = param;
    climateMode = 'live';
    highlightClimateBtn(param);
    updateClimateLegend(param, 'live');
    renderClimateHeatmapLive(param);
  }

  document.querySelectorAll('.climate-btn').forEach(btn => {
    btn.onclick = () => showClimateHeatmap(btn.dataset.param);
  });

  // Time-explorer year slider/Play button — always YEAR-based, regardless of
  // whatever the Risk Heatmap buttons last showed. Make sure there's always
  // something on screen to animate: if nothing is active yet, default to
  // Temperature so dragging/Play always renders a visible heatmap.
  function ensureClimateParamActiveForYear(){
    if(!activeClimateParam) activeClimateParam = 'Temperature_C';
    climateMode = 'year';
    highlightClimateBtn(activeClimateParam);
    updateClimateLegend(activeClimateParam, 'year');
  }

  // ---- "2000–2030 Heatmap Forecast" year slider (ported from heatmap.html) ----
  const FORECAST_START_YEAR = 2026; // matches heatmap.html's LSTM forecast cutover
  const climateYearSlider = document.getElementById('climateYearSlider');
  const climateYearLabel = document.getElementById('climateYearLabel');
  const climateEraLabel = document.getElementById('climateEraLabel');

  function updateClimateYearReadout(){
    climateYearLabel.textContent = climateYear;
    const isForecast = climateYear >= FORECAST_START_YEAR;
    climateEraLabel.textContent = isForecast ? 'FORECAST (LSTM)' : 'OBSERVED';
    document.querySelectorAll('.climate-year-ticks span').forEach(el => {
      el.classList.toggle('active', parseInt(el.dataset.year, 10) === climateYear);
    });
  }

  // Build "2000, 2005, 2010 … 2030" tick labels once, so every year milestone
  // on record is visible under the slider (not just whichever one is dragged to).
  (function buildClimateYearTicks(){
    const ticksEl = document.getElementById('climateYearTicks');
    if(!ticksEl) return;
    for(let y = 2000; y <= 2030; y += 5){
      const span = document.createElement('span');
      span.textContent = y;
      span.dataset.year = y;
      ticksEl.appendChild(span);
    }
  })();
  updateClimateYearReadout();

  climateYearSlider.addEventListener('input', () => {
    ensureClimateParamActiveForYear();
    climateYear = parseInt(climateYearSlider.value, 10);
    updateClimateYearReadout();
    renderClimateHeatmapForYear();
  });

  // Play/pause animates 2000 → 2030 → loops, same behaviour as heatmap.html's playBtn.
  const climatePlayBtn = document.getElementById('climatePlayBtn');
  let climatePlaying = false, climatePlayTimer = null;
  function climateTick(){
    let next = climateYear + 1;
    if(next > 2030) next = 2000;
    climateYear = next;
    climateYearSlider.value = next;
    ensureClimateParamActiveForYear();
    updateClimateYearReadout();
    renderClimateHeatmapForYear();
  }
  function climatePlay(){
    ensureClimateParamActiveForYear();
    climatePlaying = true;
    climatePlayBtn.textContent = '⏸';
    climatePlayTimer = setInterval(climateTick, 600);
  }
  function climatePause(){
    climatePlaying = false;
    climatePlayBtn.textContent = '▶';
    clearInterval(climatePlayTimer);
  }
  climatePlayBtn.onclick = () => (climatePlaying ? climatePause() : climatePlay());

  // All layers start off on load — nothing auto-activates. The user turns on
  // "Risk Heatmap" first, then taps Temp/Humidity/Rainfall (or drags the
  // slider/hits Play, which will auto-pick Temperature via ensureClimateParamActiveForYear()).



  /* ===================================================================
     Buffer Analysis Layer
     - Draws a dashed L.circle buffer (fixed radius) around every station
       currently at elevated risk (score >= 34).
     - Buffers restyle/redraw whenever: the toggle turns on, or the live
       risk scores change (time explorer / refresh).
     - Clicking a buffer opens a bottom "Buffer Insights" card with the
       covered area and a count of other stations that fall inside it.
     =================================================================== */

  const RISK_THRESHOLD = 34;
  let bufferLayerOn = false;
  let bufferRadiusKm = 15; // fixed buffer radius (no slider control)
  let bufferDrawerMode = null; // 'station' | 'location' — which content the shared bufferDrawer currently shows
  const BUFFER_EXCLUDED_NAMES = ['kanpur', 'lucknow']; // no buffer circle drawn around these stations, regardless of risk score

  function currentScore(station){
    return station._liveScore ?? station.risk?.score ?? null;
  }

  // Other stations whose own position falls inside this buffer circle —
  // used as the "Overlapping Weather Points / Stations" count in the insights card.
  function countOverlappingStations(station, radiusKm){
    let count = 0;
    INDIA_STATIONS.forEach(other => {
      if(other.id === station.id) return;
      if(haversineKm(station.lat, station.lon, other.lat, other.lon) <= radiusKm) count++;
    });
    return count;
  }

  function drawStationBuffers(radiusKm){
    bufferRadiusKm = radiusKm;
    bufferLayer.clearLayers(); // always clear existing buffers before redrawing

    if(!bufferLayerOn) return; // nothing to draw while the layer is switched off

    INDIA_STATIONS.forEach(station => {
      const score = currentScore(station);
      if(score === null || score < RISK_THRESHOLD) return; // risk-threshold filtering
      if(BUFFER_EXCLUDED_NAMES.some(n => station.name.toLowerCase().includes(n))) return; // Kanpur/Lucknow never get a buffer

      const rc = riskColor(score);
      const circle = L.circle([station.lat, station.lon], {
        radius: radiusKm * 1000,       // km -> meters
        color: rc,
        fillColor: rc,
        weight: 2,
        dashArray: '5, 5',
        fillOpacity: 0.15
      }).addTo(bufferLayer);

      circle.bindTooltip(
        `<b>${escapeHTML(station.name)}</b><br>Buffer radius: ${radiusKm} km<br>Risk score: ${score}/100`,
        {sticky:true}
      );

      circle.on('click', () => openBufferInsights(station, radiusKm, score));
    });
  }

  function openBufferInsights(station, radiusKm, score){
    bufferDrawerMode = 'station';
    const rc = riskColor(score);
    const rl = riskLabel(score);
    const areaKm2 = Math.PI * radiusKm * radiusKm;
    const overlapCount = countOverlappingStations(station, radiusKm);

    document.getElementById('bufferDrawerContent').innerHTML = `
      <div class="buffer-drawer-title">Buffer Insights</div>
      <div class="buffer-drawer-name">${escapeHTML(station.name)}${station.state ? ' — ' + escapeHTML(station.state) : ''}</div>
      <div class="risk-block" style="margin-bottom:12px;">
        <div class="risk-header">
          <span class="metric-label" style="margin:0;">Risk Score</span>
          <span class="risk-score-num" style="color:${rc}">${score}</span>
        </div>
        <div class="risk-bar-track"><div class="risk-bar-fill" style="width:${score}%;background:${rc}"></div></div>
        <div style="font-size:11.5px;color:var(--text-muted);margin-top:8px;">${rl} vulnerability level.</div>
      </div>
      <div class="metric-grid" style="margin-bottom:0;">
        <div class="metric-box"><div class="metric-label">Buffer Radius</div><div class="metric-value">${radiusKm} km</div></div>
        <div class="metric-box"><div class="metric-label">Impacted Area</div><div class="metric-value">${areaKm2.toFixed(0)} km²</div></div>
        <div class="metric-box" style="grid-column:1 / -1;"><div class="metric-label">Overlapping Stations</div><div class="metric-value">${overlapCount}</div></div>
      </div>
    `;
    document.getElementById('bufferDrawer').classList.add('open');
  }

  document.getElementById('bufferDrawerClose').onclick = () => {
    document.getElementById('bufferDrawer').classList.remove('open');
    if(bufferDrawerMode === 'location') clearCustomLocation();
    bufferDrawerMode = null;
  };

  // Sidebar toggle: show/hide bufferLayer on the map, and gate the whole
  // "Search Any Location" panel + its drawn buffers behind the same switch —
  // nothing from Buffer Analysis (station buffers, custom-location search,
  // custom-location buffers, or the insights drawer) shows while it's off.
  document.getElementById('rowBuffer').onclick = () => {
    const tg = document.getElementById('toggleBuffer');
    bufferLayerOn = tg.classList.toggle('on');
    document.getElementById('bufferLocPanelContent').style.display = bufferLayerOn ? 'block' : 'none';
    if(bufferLayerOn){
      map.addLayer(bufferLayer);
      map.addLayer(customLocationLayer);
      drawStationBuffers(bufferRadiusKm);
    } else {
      map.removeLayer(bufferLayer);
      bufferLayer.clearLayers();
      document.getElementById('bufferDrawer').classList.remove('open');
      bufferDrawerMode = null;
      clearCustomLocation();
      map.removeLayer(customLocationLayer);
    }
  };

  /* ===================================================================
     Location Weather Buffer
     - Lets the user search (or GPS-locate) ANY point, not just the fixed
       INDIA_STATIONS network.
     - Fetches that point's live weather via the same Open-Meteo call used
       for stations, then draws four fixed concentric buffers (5/10/15/20 km)
       colored by that location's own live risk score.
     - Reports which of the app's real weather stations fall inside each
       buffer, so the user can see live station coverage around any place.
     =================================================================== */

  const customLocationLayer = L.layerGroup(); // visibility now gated by the Buffer Analysis toggle
  const CUSTOM_BUFFER_RADII_KM = [20, 15, 10, 5]; // large -> small so smaller rings render on top
  const CUSTOM_RING_OPACITY = {20:0.14, 15:0.20, 10:0.27, 5:0.34};
  const CUSTOM_RING_COLOR = {20:'#FFDDB3', 15:'#FFB870', 10:'#F2914A', 5:'#E4671E'}; // shades of orange, light (outer) -> deep (inner)
  let lastCustomLocation = null; // {point, data, risk} — cached so re-clicking the marker doesn't refetch

  function setBufferLocStatus(msg){
    document.getElementById('bufferLocStatus').textContent = msg;
  }

  function customLocationIcon(color){
    return L.divIcon({
      className:'',
      html:`<div style="width:24px;height:24px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);
        background:rgba(15,22,40,0.92);border:2px solid ${color};box-shadow:0 0 10px ${color}88;"></div>`,
      iconSize:[24,24], iconAnchor:[12,24]
    });
  }

  function drawCustomLocationBuffers(point, risk){
    customLocationLayer.clearLayers();

    CUSTOM_BUFFER_RADII_KM.forEach(r => {
      const ringColor = CUSTOM_RING_COLOR[r];
      const stationsInRange = INDIA_STATIONS.filter(s => haversineKm(point.lat, point.lon, s.lat, s.lon) <= r);
      const circle = L.circle([point.lat, point.lon], {
        radius: r * 1000, // km -> meters
        color: ringColor,
        fillColor: ringColor,
        weight: 2,
        dashArray: '6, 4',
        fillOpacity: CUSTOM_RING_OPACITY[r]
      }).addTo(customLocationLayer);

      circle.bindTooltip(
        `<b>${r} km buffer</b><br>Risk score: ${risk.score}/100<br>${stationsInRange.length ? stationsInRange.length + ' station(s) in range' : 'No stations in range'}`,
        {sticky:true}
      );
      circle.on('click', () => openLocationBufferInsights(point, lastCustomLocation.data, risk));
    });

    L.marker([point.lat, point.lon], {icon: customLocationIcon(CUSTOM_RING_COLOR[5])})
      .addTo(customLocationLayer)
      .bindTooltip(point.label || 'Selected location')
      .on('click', () => openLocationBufferInsights(point, lastCustomLocation.data, risk));
  }

  function openLocationBufferInsights(point, data, risk){
    bufferDrawerMode = 'location';
    const rc = riskColor(risk.score);
    const rl = riskLabel(risk.score);
    const [wLabel, wIcon] = wmoInfo(data.current.weathercode);

    const ringsHtml = CUSTOM_BUFFER_RADII_KM.slice().sort((a,b) => a - b).map(r => {
      const stations = INDIA_STATIONS.filter(s => haversineKm(point.lat, point.lon, s.lat, s.lon) <= r);
      return `<div class="buffer-ring-row">
        <span class="buffer-ring-swatch" style="background:${CUSTOM_RING_COLOR[r]}"></span>
        <div class="buffer-ring-info">
          <div class="buffer-ring-head">${r} km</div>
          <div class="buffer-ring-stations">${stations.length ? escapeHTML(stations.map(s => s.name).join(', ')) : 'No weather stations in range'}</div>
        </div>
      </div>`;
    }).join('');

    document.getElementById('bufferDrawerContent').innerHTML = `
      <div class="buffer-drawer-title">Location Weather Buffer</div>
      <div class="buffer-drawer-name">${escapeHTML(point.label || 'Selected Location')}</div>
      <div class="current-conditions" style="margin-bottom:12px;">
        <div class="cc-icon">${wIcon}</div>
        <div>
          <div class="cc-label">${wLabel}</div>
          <div class="cc-sub">${data.current.temperature_2m.toFixed(1)}°C · ${Math.round(data.current.relative_humidity_2m)}% humidity · ${Math.round(data.current.wind_speed_10m)} km/h wind</div>
        </div>
      </div>
      <div class="risk-block" style="margin-bottom:12px;">
        <div class="risk-header">
          <span class="metric-label" style="margin:0;">Live Risk Score</span>
          <span class="risk-score-num" style="color:${rc}">${risk.score}</span>
        </div>
        <div class="risk-bar-track"><div class="risk-bar-fill" style="width:${risk.score}%;background:${rc}"></div></div>
        <div style="font-size:11.5px;color:var(--text-muted);margin-top:8px;">${rl} vulnerability · ${risk.rainfall24h}mm rain in the last 24h.</div>
      </div>
      <div class="metric-label" style="margin-bottom:8px;">Buffer Zones &amp; Station Overlap</div>
      <div class="buffer-ring-list">${ringsHtml}</div>
    `;
    document.getElementById('bufferDrawer').classList.add('open');
  }

  async function selectCustomLocation(point){
    setBufferLocStatus('Fetching live weather for ' + (point.label || 'this location') + '…');
    try{
      const data = await fetchStationData({lat: point.lat, lon: point.lon});
      const risk = computeRisk(data.hourlyRain, data.current, data.daily);
      lastCustomLocation = {point, data, risk};
      drawCustomLocationBuffers(point, risk);
      openLocationBufferInsights(point, data, risk);
      map.flyTo([point.lat, point.lon], 10, {duration:1});
      setBufferLocStatus('Showing live buffer analysis for ' + (point.label || `${point.lat.toFixed(3)}, ${point.lon.toFixed(3)}`) + '.');
    }catch(err){
      setBufferLocStatus("Couldn't fetch weather for this location — try again.");
    }
  }

  function wireBufferLocationAutocomplete(){
    const input = document.getElementById('bufferLocInput');
    const suggestBox = document.getElementById('bufferLocSuggest');
    let debounceTimer = null;
    let lastResults = [];

    input.addEventListener('input', () => {
      clearTimeout(debounceTimer);
      const q = input.value;
      debounceTimer = setTimeout(async () => {
        lastResults = await geocodePlace(q);
        if(!lastResults.length){ suggestBox.classList.remove('show'); return; }
        suggestBox.innerHTML = lastResults.map((r,i) =>
          `<div class="route-suggest-item" data-i="${i}">
             <div class="rs-name">${escapeHTML(r.label.split(',')[0])}</div>
             <div class="rs-sub">${escapeHTML(r.label.split(',').slice(1).join(',').trim())}</div>
           </div>`).join('');
        suggestBox.querySelectorAll('.route-suggest-item').forEach(item => {
          item.onclick = () => {
            const picked = lastResults[+item.dataset.i];
            input.value = picked.label;
            suggestBox.classList.remove('show');
            selectCustomLocation(picked);
          };
        });
        suggestBox.classList.add('show');
      }, 300);
    });

    input.addEventListener('keydown', async e => {
      if(e.key !== 'Enter') return;
      e.preventDefault();
      const q = input.value.trim();
      if(!q) return;
      suggestBox.classList.remove('show');
      const results = lastResults.length ? lastResults : await geocodePlace(q);
      if(results.length) selectCustomLocation(results[0]);
      else setBufferLocStatus('No matching location found — try a different search.');
    });

    document.addEventListener('click', e => {
      if(!e.target.closest('#bufferLocInput') && !e.target.closest('#bufferLocSuggest')) suggestBox.classList.remove('show');
    });
  }
  wireBufferLocationAutocomplete();

  document.getElementById('bufferLocGps').onclick = () => {
    if(!navigator.geolocation){ setBufferLocStatus('Geolocation not supported by this browser.'); return; }
    setBufferLocStatus('Getting your location…');
    navigator.geolocation.getCurrentPosition(pos => {
      const point = {lat: pos.coords.latitude, lon: pos.coords.longitude, label: 'My current location'};
      document.getElementById('bufferLocInput').value = point.label;
      selectCustomLocation(point);
    }, () => setBufferLocStatus('Location access denied — try searching instead.'));
  };

  function clearCustomLocation(){
    document.getElementById('bufferLocInput').value = '';
    setBufferLocStatus('');
    customLocationLayer.clearLayers();
    lastCustomLocation = null;
  }

  document.getElementById('bufferLocClear').onclick = () => {
    clearCustomLocation();
    document.getElementById('bufferDrawer').classList.remove('open');
    bufferDrawerMode = null;
  };

  /* ===== Local feedback (residents share info about this location) ===== */
  function crowdReportHtml(station){
    return `<div class="fb-box">
      <div class="fb-title">💬 Local feedback</div>
      <div class="fb-sub">Live here or nearby? Share what you're seeing — it helps others get real, on-the-ground info about this area.</div>
      <select id="fbType" class="fb-select">
        <option>General update</option>
        <option>Waterlogging / flooding</option>
        <option>Heavy rain</option>
        <option>Road blocked</option>
        <option>Power cut</option>
        <option>All clear</option>
      </select>
      <textarea id="fbText" class="fb-textarea" rows="3" data-i18n-placeholder="feedbackPlaceholder" placeholder="e.g. Water collecting near the market road, avoid that side..."></textarea>
      <button class="fb-send" id="fbSend">Post feedback</button>
      <div class="fb-thanks" id="fbThanks">✓ Thanks! Your feedback was shared for this area.</div>
      <div class="fb-feed" id="fbFeed"></div>
    </div>`;
  }


  /* ===================================================================
     Weather-safe A→B route planner
     - Start/destination can be set by typed place name (geocoded via
       Open-Meteo's free geocoding API), GPS (start only), or by pinning
       a point on the map.
     - Risk is checked in two layers:
         1) your loaded weather stations (rich, multi-factor risk score)
         2) points sampled every ~25km along the ACTUAL baseline road
            route, each checked for rainfall independently — this is
            what fixes the old "only 24 fixed stations" blind spot,
            since most of any given road is nowhere near a station.
       Any point over the risk threshold becomes a circular "avoid zone"
       sent to OpenRouteService, which reroutes the real road path
       around it where a viable road exists.
     =================================================================== */

  let routeStart = null, routeEnd = null;           // {lat, lon, label}
  let routeStartMarker = null, routeEndMarker = null;
  let routeAvoidLayer = L.layerGroup().addTo(map); // visible proof of what the route is dodging
  let routePinMode = null;                          // 'start' | 'end' | null
  let routeLayerOn = false;                          // whole planner is opt-in, like Stations/Risk/Buffer

  function routeStatus(text){
    const el = document.getElementById('routeStatus');
    if(el) el.textContent = text;
  }

  function setRoutePoint(which, point){
    document.getElementById('routeClose').style.display = 'block';
    if(which === 'start'){
      routeStart = point;
      if(routeStartMarker) map.removeLayer(routeStartMarker);
      routeStartMarker = L.circleMarker([point.lat, point.lon], {radius:7, color:'#4ADE80', fillColor:'#4ADE80', fillOpacity:1})
        .addTo(map).bindTooltip('Start: ' + (point.label || 'pinned point'));
      document.getElementById('routeStartInput').value = point.label || `${point.lat.toFixed(4)}, ${point.lon.toFixed(4)}`;
    } else {
      routeEnd = point;
      if(routeEndMarker) map.removeLayer(routeEndMarker);
      routeEndMarker = L.circleMarker([point.lat, point.lon], {radius:7, color:'#E4573D', fillColor:'#E4573D', fillOpacity:1})
        .addTo(map).bindTooltip('Destination: ' + (point.label || 'pinned point'));
      document.getElementById('routeEndInput').value = point.label || `${point.lat.toFixed(4)}, ${point.lon.toFixed(4)}`;
    }
  }

  // ---- Geocoding (typed place name -> coordinates) ----
  async function geocodePlace(query){
    if(!query || query.trim().length < 2) return [];
    try{
      const url = `${GEOCODE_URL}?name=${encodeURIComponent(query.trim())}&count=5&language=en&format=json`;
      const res = await fetch(url);
      if(!res.ok) return [];
      const data = await res.json();
      return (data.results || []).map(r => ({
        lat: r.latitude, lon: r.longitude,
        label: [r.name, r.admin1, r.country].filter(Boolean).join(', ')
      }));
    }catch(err){ return []; }
  }

  function wireRouteAutocomplete(inputId, suggestId, which){
    const input = document.getElementById(inputId);
    const suggestBox = document.getElementById(suggestId);
    let debounceTimer = null;
    input.addEventListener('input', () => {
      clearTimeout(debounceTimer);
      const q = input.value;
      debounceTimer = setTimeout(async () => {
        const results = await geocodePlace(q);
        if(!results.length){ suggestBox.classList.remove('show'); return; }
        suggestBox.innerHTML = results.map((r,i) =>
          `<div class="route-suggest-item" data-i="${i}">
             <div class="rs-name">${r.label.split(',')[0]}</div>
             <div class="rs-sub">${r.label.split(',').slice(1).join(',').trim()}</div>
           </div>`).join('');
        suggestBox.querySelectorAll('.route-suggest-item').forEach(item => {
          item.onclick = () => {
            const picked = results[+item.dataset.i];
            setRoutePoint(which, picked);
            suggestBox.classList.remove('show');
          };
        });
        suggestBox.classList.add('show');
      }, 300);
    });
    document.addEventListener('click', e => {
      if(!e.target.closest('.route-field')) suggestBox.classList.remove('show');
    });
  }
  wireRouteAutocomplete('routeStartInput', 'routeStartSuggest', 'start');
  wireRouteAutocomplete('routeEndInput', 'routeEndSuggest', 'end');

  // ---- GPS for start ----
  document.getElementById('routeStartGps').onclick = () => {
    if(!navigator.geolocation){ routeStatus('Geolocation not supported by this browser.'); return; }
    routeStatus('Getting your location…');
    navigator.geolocation.getCurrentPosition(pos => {
      setRoutePoint('start', {lat: pos.coords.latitude, lon: pos.coords.longitude, label: 'My location'});
      routeStatus('Start set to your current location.');
    }, () => routeStatus('Location access denied — pin your start on the map instead.'));
  };

  // ---- Pin-on-map for start/end ----
  function setPinMode(which, btn){
    routePinMode = routePinMode === which ? null : which;
    document.getElementById('routeStartPin').classList.toggle('active', routePinMode === 'start');
    document.getElementById('routeEndPin').classList.toggle('active', routePinMode === 'end');
    if(routePinMode) routeStatus(`Click the map to set your ${which === 'start' ? 'start point' : 'destination'}…`);
  }
  document.getElementById('routeStartPin').onclick = function(){ setPinMode('start', this); };
  document.getElementById('routeEndPin').onclick = function(){ setPinMode('end', this); };

  /* ---- Click anywhere on the map to see that spot's live weather ----
     Reuses the same "virtual station" approach as the GPS Locate-Me button:
     drop a temporary pin, reverse-geocode it for a readable name, fetch live
     weather + risk for the exact point clicked, and open it in the same
     drawer used for the fixed station network — so a random tap anywhere on
     the map (not just a station icon or a search result) shows live weather. */
  let clickWeatherRequestId = 0; // guards a slow request from overwriting a newer click's result

  function clickWeatherIcon(){
    return L.divIcon({
      className:'',
      html:`<div style="width:16px;height:16px;border-radius:50%;background:#4FD9D0;
        border:2px solid rgba(15,22,40,0.92);box-shadow:0 0 8px rgba(79,217,208,0.7);"></div>`,
      iconSize:[16,16], iconAnchor:[8,8]
    });
  }

  // Formats a raw lat/lon pair into a readable coordinate string with N/S and
  // E/W suffixes (e.g. 19.0760°N, 72.8777°E) — shown under the location name
  // in the drawer, in the same spot a real station's code (e.g. IMD-AWS-...)
  // normally goes, since a clicked point has no station code of its own.
  function formatLatLon(lat, lon){
    const ns = lat >= 0 ? 'N' : 'S';
    const ew = lon >= 0 ? 'E' : 'W';
    return `${Math.abs(lat).toFixed(4)}°${ns}, ${Math.abs(lon).toFixed(4)}°${ew}`;
  }

  async function showWeatherForClickedPoint(lat, lon){
    const requestId = ++clickWeatherRequestId;

    if(clickWeatherMarker) map.removeLayer(clickWeatherMarker);
    clickWeatherMarker = L.marker([lat, lon], {icon: clickWeatherIcon()})
      .addTo(map)
      .bindPopup('Fetching live weather…')
      .openPopup();

    const pointStation = {
      id: 'clicked-' + Date.now(), code: formatLatLon(lat, lon),
      name: `${lat.toFixed(3)}, ${lon.toFixed(3)}`, state: '', type: 'AWS', lat, lon
    };

    // Reverse-geocode for a readable name — same call the Locate-Me button uses.
    try{
      const rev = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}&zoom=16&addressdetails=1`, {headers:{'Accept':'application/json'}});
      const rj = await rev.json();
      const a = rj.address || {};
      const area = a.suburb || a.neighbourhood || a.quarter || a.hamlet || a.village || a.town || a.residential || '';
      const locality = a.city_district || a.suburb || '';
      const city = a.city || a.town || a.municipality || a.county || a.state_district || '';
      const st = a.state || '';
      const parts = [];
      [area, locality, city].forEach(p => { if(p && !parts.includes(p)) parts.push(p); });
      pointStation.name = parts.length ? parts.join(', ') : (rj.display_name ? rj.display_name.split(',').slice(0,3).join(',') : pointStation.name);
      pointStation.state = st || city || '';
    }catch(err){ /* keep the lat/lon label if reverse geocoding fails */ }

    if(requestId !== clickWeatherRequestId) return; // a newer click already superseded this one

    const nearest = findNearestStation(lat, lon);
    if(nearest) pointStation.nearest = nearest;

    try{
      const data = await fetchStationData(pointStation);
      if(requestId !== clickWeatherRequestId) return;
      pointStation.data = data;
      pointStation.risk = computeRisk(data.hourlyRain, data.current, data.daily);
      pointStation._liveScore = pointStation.risk.score;
      pointStation._liveTemp = data.current.temperature_2m;
      pointStation._liveRain = data.current.precipitation;
      if(clickWeatherMarker) clickWeatherMarker.setPopupContent(pointStation.name);
      openDrawer(pointStation);
    }catch(err){
      console.error(err);
      if(requestId === clickWeatherRequestId && clickWeatherMarker){
        clickWeatherMarker.setPopupContent("Couldn't fetch live weather for this spot — try again.");
      }
    }
  }

  map.on('click', (e) => {
    if(routePinMode){
      setRoutePoint(routePinMode, {lat: e.latlng.lat, lon: e.latlng.lng, label: null});
      routeStatus(routePinMode === 'start' ? 'Start point pinned. Now set your destination.' : 'Destination pinned. Click "Find weather-safe route".');
      routePinMode = null;
      document.getElementById('routeStartPin').classList.remove('active');
      document.getElementById('routeEndPin').classList.remove('active');
      return;
    }
    showWeatherForClickedPoint(e.latlng.lat, e.latlng.lng);
  });

  // ---- Geometry helpers ----
  // Approximates a circle as a closed GeoJSON ring (lon,lat order) for ORS avoid_polygons.
  function circleToRing(lat, lon, radiusMeters, points){
    points = points || 16;
    const coords = [];
    const radiusKm = radiusMeters / 1000;
    const latRad = lat * Math.PI / 180;
    for(let i = 0; i <= points; i++){
      const angle = (i / points) * 2 * Math.PI;
      const dLat = (radiusKm * Math.sin(angle)) / 110.574;
      const dLon = (radiusKm * Math.cos(angle)) / (111.320 * Math.cos(latRad));
      coords.push([lon + dLon, lat + dLat]);
    }
    return coords;
  }

  // Loaded stations at/above threshold become avoid-zones (uses the app's real multi-factor risk score).
  // IMPORTANT: only counts stations near THIS route's corridor — otherwise a high-risk
  // station on the other side of the country would get flagged as "on this route" and
  // padded into the avoid_polygons request for no reason.
  function buildStationAvoidZones(threshold, routeSamples){
    threshold = threshold === undefined ? 40 : threshold;
    const CORRIDOR_KM = 40; // how far a station can be from the route and still plausibly affect it
    const zones = [];
    Object.values(markers).forEach(({station}) => {
      const score = station._liveScore ?? (station.risk ? station.risk.score : 0);
      if(score < threshold) return;
      if(routeSamples && routeSamples.length){
        const nearestKm = Math.min(...routeSamples.map(p => haversineKm(station.lat, station.lon, p.lat, p.lon)));
        if(nearestKm > CORRIDOR_KM) return; // too far from this specific route to matter
      }
      zones.push({lat: station.lat, lon: station.lon, radius: 20000 + score * 500, score, label: station.name, source: 'station'});
    });
    return zones;
  }

  // Sample points every `everyKm` along a route's actual road geometry.
  function sampleRouteEvery(coords, everyKm){
    const samples = [{lat: coords[0][1], lon: coords[0][0]}];
    let acc = 0;
    for(let i = 1; i < coords.length; i++){
      const [lon1, lat1] = coords[i-1], [lon2, lat2] = coords[i];
      acc += haversineKm(lat1, lon1, lat2, lon2);
      if(acc >= everyKm){ samples.push({lat: lat2, lon: lon2}); acc = 0; }
    }
    // cap sample count so the weather batch call stays reasonable
    if(samples.length > 40){
      const step = Math.ceil(samples.length / 40);
      return samples.filter((_, i) => i % step === 0);
    }
    return samples;
  }

  // Batch-fetch rainfall for every sampled point in ONE request (Open-Meteo accepts
  // comma-separated lat/lon lists and returns one result per point). This is a
  // lighter, rain-only version of the station risk score (24h rainfall / 75mm),
  // since fetching the full multi-factor inputs for 40 route points per request
  // would be excessive — it's deliberately consistent with, not identical to,
  // the station model's dominant 45%-weighted rainfall component.
  async function fetchRouteWeatherRisk(samples){
    if(!samples.length) return [];
    const lats = samples.map(s => s.lat).join(',');
    const lons = samples.map(s => s.lon).join(',');
    const url = `https://api.open-meteo.com/v1/forecast?latitude=${lats}&longitude=${lons}&hourly=precipitation&past_days=1&forecast_days=1&timezone=UTC`;
    try{
      const res = await fetch(url);
      if(!res.ok) return [];
      const data = await res.json();
      const list = Array.isArray(data) ? data : [data]; // single-point requests return an object, not an array
      return list.map((d, i) => {
        const rain = (d.hourly && d.hourly.precipitation) || [];
        const recent = rain.slice(Math.max(0, rain.length - 24));
        const sum = recent.reduce((a,b) => a + (Number(b) || 0), 0);
        return { lat: samples[i].lat, lon: samples[i].lon, score: Math.min(Math.round((sum/75)*100), 100), rainfall24h: Math.round(sum*10)/10 };
      });
    }catch(err){ return []; }
  }

  async function callORS(body){
    return fetch(`${ORS_CONFIG.base}/v2/directions/driving-car/geojson`, {
      method: 'POST',
      headers: { 'Authorization': ORS_CONFIG.apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
  }

  // Two persistent lines instead of one — shortest route and weather-safe route
  // are shown TOGETHER, like Google Maps' primary vs. alternate route, so you can
  // actually compare them rather than only ever seeing whichever one "won."
  let routeLineDirect = null, routeLineSafe = null;
  let routeSampleLayer = L.layerGroup().addTo(map);

  function clearRouteLines(){
    if(routeLineDirect){ map.removeLayer(routeLineDirect); routeLineDirect = null; }
    if(routeLineSafe){ map.removeLayer(routeLineSafe); routeLineSafe = null; }
    routeAvoidLayer.clearLayers();
    routeSampleLayer.clearLayers();
    document.getElementById('routeCompare').style.display = 'none';
  }

  // Full reset: wipes the route lines/zones, the start & destination pins,
  // the input fields and status text — used both when the "Close route"
  // button is clicked and when the Weather-Safe Route layer is switched off.
  function resetRoutePlanner(){
    clearRouteLines();
    if(routeStartMarker){ map.removeLayer(routeStartMarker); routeStartMarker = null; }
    if(routeEndMarker){ map.removeLayer(routeEndMarker); routeEndMarker = null; }
    routeStart = null; routeEnd = null;
    routePinMode = null;
    document.getElementById('routeStartPin').classList.remove('active');
    document.getElementById('routeEndPin').classList.remove('active');
    document.getElementById('routeStartInput').value = '';
    document.getElementById('routeEndInput').value = '';
    document.getElementById('routeStartSuggest').classList.remove('show');
    document.getElementById('routeEndSuggest').classList.remove('show');
    routeStatus('');
    document.getElementById('routeClose').style.display = 'none';
  }

  // Sidebar toggle: the whole planner (inputs + drawn route) is opt-in —
  // mirrors how Stations/Risk Heatmap/Buffer Analysis behave. Turning it
  // off clears everything the layer had drawn, same as those layers do.
  document.getElementById('rowRoute').onclick = () => {
    const tg = document.getElementById('toggleRoute');
    routeLayerOn = tg.classList.toggle('on');
    document.getElementById('routePanelContent').style.display = routeLayerOn ? 'block' : 'none';
    if(!routeLayerOn) resetRoutePlanner();
  };

  document.getElementById('routeClose').onclick = () => resetRoutePlanner();

  function drawDirectRoute(feature){
    const latlngs = feature.geometry.coordinates.map(([lon,lat]) => [lat, lon]);
    routeLineDirect = L.polyline(latlngs, {color:'#E4573D', weight:5, opacity:0.85, dashArray:'10 8'}).addTo(map);
    return routeLineDirect;
  }
  function drawSafeRouteLine(feature){
    const latlngs = feature.geometry.coordinates.map(([lon,lat]) => [lat, lon]);
    routeLineSafe = L.polyline(latlngs, {color:'#4FD9D0', weight:5, opacity:0.9}).addTo(map);
    return routeLineSafe;
  }

  // Draws every disturbance as a translucent circle with a tooltip explaining
  // WHY it's flagged — this is the visual proof of what's wrong on the direct route,
  // not just a claim in the status text. Colored by riskColor(z.score) — the same
  // green/amber/red scale used everywhere else in the app — so a glance at the map
  // shows which zones are the mild ones and which are the genuinely severe ones,
  // instead of every disturbance looking equally alarming in flat red.
  function drawAvoidZones(zones){
    routeAvoidLayer.clearLayers();
    zones.forEach(z => {
      const zc = riskColor(z.score);
      const circle = L.circle([z.lat, z.lon], {
        radius: z.radius, color: zc, weight: 2, fillColor: zc, fillOpacity: 0.18 + (z.score/100) * 0.22, dashArray: '6 4'
      }).addTo(routeAvoidLayer);
      const sourceLabel = z.source === 'station' ? `Station: ${z.label}` : `Live rainfall on this road segment — ${z.label}`;
      circle.bindTooltip(`⚠️ ${riskLabel(z.score)} weather disturbance — risk ${z.score}/100<br/>${sourceLabel}`, {sticky:true});
    });
  }

  // Small dots for every sampled point, colored by risk — visible whether or not
  // anything crosses the disturbance threshold, so "the road was actually checked
  // against live weather" is something you can see, not just claim.
  function drawSampleDots(riskPoints){
    routeSampleLayer.clearLayers();
    riskPoints.forEach(p => {
      L.circleMarker([p.lat, p.lon], {
        radius: 4, weight: 1, color: '#0b0f1a', fillColor: riskColor(p.score), fillOpacity: 0.9
      }).addTo(routeSampleLayer).bindTooltip(`${p.rainfall24h}mm/24h — risk ${p.score}/100`, {sticky:true});
    });
  }

  function routeLegendHtml(){
    return `<div class="rc-legend">
      <span><span class="rc-swatch" style="border-color:var(--accent-red);border-top-style:dashed;"></span>Shortest route</span>
      <span><span class="rc-swatch" style="border-color:var(--accent-cyan);"></span>Weather-safe route</span>
    </div>`;
  }

  // Renders the Google-Maps-style comparison: one card per route, with the
  // time/distance delta between them spelled out explicitly.
  function renderRouteComparison(directFeature, safeFeature, zones){
    const compare = document.getElementById('routeCompare');
    const dKm = directFeature.properties.summary.distance / 1000;
    const dMin = Math.round(directFeature.properties.summary.duration / 60);

    let html = routeLegendHtml();
    html += `<div class="rc-card rc-direct">
      <div class="rc-card-head"><span class="rc-card-title">🔴 Shortest route</span><span class="rc-card-time">${dMin} min</span></div>
      <div class="rc-card-sub">${dKm.toFixed(1)} km · passes through ${zones.length} weather disturbance${zones.length===1?'':'s'}</div>
      ${zones.length ? `<div class="rc-issue-list">${zones.map(z =>
        `<div class="rc-issue"><b>⚠️ ${z.source==='station' ? z.label : 'On road'}</b> — risk ${z.score}/100${z.source==='route' ? ' · '+z.label : ''}</div>`
      ).join('')}</div>` : ''}
    </div>`;

    if(safeFeature){
      const sKm = safeFeature.properties.summary.distance / 1000;
      const sMin = Math.round(safeFeature.properties.summary.duration / 60);
      const deltaMin = sMin - dMin;
      const deltaKm = sKm - dKm;
      const deltaText = deltaMin === 0 ? 'same travel time as the shortest route'
        : deltaMin > 0 ? `+${deltaMin} min longer than the shortest route`
        : `${Math.abs(deltaMin)} min faster than the shortest route`;
      const deltaColor = deltaMin > 0 ? 'var(--accent-amber)' : 'var(--accent-cyan)';
      html += `<div class="rc-card rc-safe">
        <div class="rc-card-head"><span class="rc-card-title">🟢 Weather-safe route</span><span class="rc-card-time">${sMin} min</span></div>
        <div class="rc-card-sub">${sKm.toFixed(1)} km · avoids all ${zones.length} disturbance${zones.length===1?'':'s'} above</div>
        <div class="rc-delta" style="color:${deltaColor}">${deltaText}${Math.abs(deltaKm) >= 0.1 ? ` (${deltaKm>0?'+':''}${deltaKm.toFixed(1)} km)` : ''}</div>
      </div>`;
    } else {
      html += `<div class="rc-card" style="border-color:var(--accent-amber);">
        <div class="rc-card-title" style="color:var(--accent-amber);">⚠️ No safer alternative on this road network</div>
        <div class="rc-card-sub">Every viable road is inside the flagged zone(s) — the shortest route above is your only option right now.</div>
      </div>`;
    }
    compare.innerHTML = html;
    compare.style.display = 'block';
  }

  function renderCleanRouteCard(feature){
    const km = (feature.properties.summary.distance / 1000).toFixed(1);
    const min = Math.round(feature.properties.summary.duration / 60);
    document.getElementById('routeCompare').innerHTML = `<div class="rc-card rc-safe">
      <div class="rc-card-head"><span class="rc-card-title">🟢 Weather-safe route</span><span class="rc-card-time">${min} min</span></div>
      <div class="rc-card-sub">${km} km · this is also the shortest route — no weather disturbance found anywhere along it right now.</div>
    </div>`;
    document.getElementById('routeCompare').style.display = 'block';
  }

  async function fetchWeatherSafeRoute(){
    if(!routeStart || !routeEnd){ routeStatus('Set both a start and a destination first.'); return; }
    if(!ORS_CONFIG.apiKey || ORS_CONFIG.apiKey === "PASTE_YOUR_OPENROUTESERVICE_KEY_HERE"){
      routeStatus('Add a free OpenRouteService key to ORS_CONFIG.apiKey to enable routing.');
      return;
    }

    clearRouteLines();
    routeStatus('Calculating the shortest route…');
    try{
      const coords = [[routeStart.lon, routeStart.lat],[routeEnd.lon, routeEnd.lat]];
      const baseRes = await callORS({ coordinates: coords });
      if(!baseRes.ok){ routeStatus('Routing failed — check your ORS key/quota, or the points may be unreachable by road.'); return; }
      const baseGeo = await baseRes.json();
      const baseFeature = baseGeo.features && baseGeo.features[0];
      if(!baseFeature){ routeStatus('No route found between those points.'); return; }

      // Always draw the shortest route first, in red — this is the reference
      // path everything else gets compared against.
      drawDirectRoute(baseFeature);
      map.fitBounds(routeLineDirect.getBounds(), {padding:[70,70]});
      routeStatus('Checking live weather along this route…');

      const routeCoords = baseFeature.geometry.coordinates; // [lon,lat] pairs along the real road path
      const samples = sampleRouteEvery(routeCoords, 25);
      const riskPoints = await fetchRouteWeatherRisk(samples);
      drawSampleDots(riskPoints); // proof the corridor was actually checked against live data

      const stationZones = buildStationAvoidZones(40, samples);
      const routeZones = riskPoints.filter(p => p.score >= 40).map(p =>
        ({lat: p.lat, lon: p.lon, radius: 15000 + p.score * 400, score: p.score, label: `${p.rainfall24h}mm/24h`, source: 'route'})
      );
      const allZones = stationZones.concat(routeZones);

      if(allZones.length === 0){
        // shortest route is already clear — recolor it green/solid rather than
        // drawing two identical overlapping lines
        map.removeLayer(routeLineDirect); routeLineDirect = null;
        drawSafeRouteLine(baseFeature);
        map.fitBounds(routeLineSafe.getBounds(), {padding:[70,70]});
        routeStatus(`Checked ${riskPoints.length} points against live weather data — no disturbance found. Shortest route is already weather-safe.`);
        renderCleanRouteCard(baseFeature);
        return;
      }

      drawAvoidZones(allZones);
      routeStatus(`Found ${allZones.length} weather disturbance(s) on the shortest route — calculating a safer alternative…`);

      const allPolys = allZones.map(z => [circleToRing(z.lat, z.lon, z.radius)]);
      const avoidRes = await callORS({ coordinates: coords, options: { avoid_polygons: { type: 'MultiPolygon', coordinates: allPolys } } });
      let safeFeature = null;
      if(avoidRes.ok){
        const avoidGeo = await avoidRes.json();
        const candidate = avoidGeo.features && avoidGeo.features[0];
        // only count it as a genuinely different "safe route" if ORS actually
        // rerouted (avoid_polygons silently returns the same path when it can't detour)
        if(candidate && Math.abs(candidate.properties.summary.distance - baseFeature.properties.summary.distance) > 500){
          safeFeature = candidate;
        }
      }

      if(safeFeature){
        drawSafeRouteLine(safeFeature);
        const bounds = routeLineDirect.getBounds().extend(routeLineSafe.getBounds());
        map.fitBounds(bounds, {padding:[70,70]});
        const dMin = Math.round(baseFeature.properties.summary.duration/60);
        const sMin = Math.round(safeFeature.properties.summary.duration/60);
        const deltaMin = sMin - dMin;
        routeStatus(`Both routes plotted. Weather-safe route is ${deltaMin===0?'the same time as':deltaMin>0?`${deltaMin} min longer than`:`${Math.abs(deltaMin)} min faster than`} the shortest route.`);
      } else {
        routeStatus(`No safer route exists on this road network — showing the shortest route with ${allZones.length} disturbance(s) marked in red.`);
      }
      renderRouteComparison(baseFeature, safeFeature, allZones);
    }catch(err){
      routeStatus('Routing request failed — network or CORS error. See console.');
      console.error(err);
    }
  }
  document.getElementById('routeFind').onclick = fetchWeatherSafeRoute;

  // check a citizen report against the station's actual data, return Verified/Unconfirmed
  function verifyReport(station, cond){
    const rain24 = station.risk ? station.risk.rainfall24h : 0;
    const nowRain = station.data ? (station.data.current.precipitation || 0) : 0;
    let verified, expl, confidence;
    if(cond === 'flooding'){
      verified = rain24 >= 40;
      confidence = Math.min(100, Math.round((rain24 / 60) * 100));
      expl = verified ? `Station recorded ${rain24}mm in 24h — heavy rainfall supports a flooding report.`
                      : `Station shows only ${rain24}mm in 24h — not enough rain to confirm flooding yet.`;
    } else if(cond === 'heavy_rain'){
      verified = rain24 >= 15 || nowRain >= 2;
      confidence = Math.min(100, Math.round((Math.max(rain24, nowRain*10) / 30) * 100));
      expl = verified ? `Station shows ${rain24}mm/24h (${nowRain}mm now) — consistent with heavy rain.`
                      : `Station shows ${rain24}mm/24h (${nowRain}mm now) — no significant rain detected.`;
    } else { // dry
      verified = rain24 < 5 && nowRain < 0.5;
      confidence = verified ? Math.round(100 - (rain24 / 5) * 100) : Math.min(100, Math.round((rain24 / 20) * 100));
      expl = verified ? `Station shows ${rain24}mm/24h — dry conditions confirmed.`
                      : `Station recorded ${rain24}mm/24h — that contradicts a "dry" report.`;
    }
    return {verified, expl, confidence: Math.max(0, Math.min(100, confidence))};
  }

  /* ===== Search bar (find a city/state, fly the map, open its drawer) ===== */
  const searchInput = document.getElementById('searchInput');
  const searchResults = document.getElementById('searchResults');
  let searchDebounce = null;

  function runSearch(q){
    q = q.trim();
    if(!q){ searchResults.classList.remove('show'); return; }
    const lower = q.toLowerCase();

    // 1) instant matches from our own stations
    const matches = INDIA_STATIONS.filter(s =>
      s.name.toLowerCase().includes(lower) || s.state.toLowerCase().includes(lower)
    ).slice(0, 4);

    let html = '';
    if(matches.length){
      html += matches.map(s =>
        `<div class="search-item" data-id="${s.id}">
           <div class="si-name">${s.name}</div><div class="si-state">${s.state} · station</div>
         </div>`).join('');
    }
    html += `<div class="search-loading" id="searchLoading">Searching all areas of India…</div>`;
    searchResults.innerHTML = html;
    searchResults.classList.add('show');
    searchResults.querySelectorAll('.search-item[data-id]').forEach(item => {
      item.onclick = () => selectStationById(+item.dataset.id);
    });

    // 2) area/block/locality search via Nominatim (any small place in India)
    clearTimeout(searchDebounce);
    searchDebounce = setTimeout(() => geoAreaSearch(q, matches.length), 400);
  }

  async function geoAreaSearch(q, hadStations){
    try{
      const url = `https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=7&countrycodes=in&q=${encodeURIComponent(q)}`;
      const res = await fetch(url, {headers:{'Accept':'application/json'}});
      const data = await res.json();
      const loader = document.getElementById('searchLoading');
      if(!Array.isArray(data) || !data.length){
        if(loader) loader.outerHTML = hadStations ? '' : `<div class="search-empty">No place found for "${q}"</div>`;
        return;
      }
      const items = data.map(p => {
        const a = p.address || {};
        // main = the most specific name available (institute/building/POI first, then locality)
        const poi = a.amenity || a.building || a.office || a.university || a.college || a.school || a.hospital || a.shop || a.tourism || '';
        const first = (p.display_name || '').split(',')[0].trim();
        const main = poi || first || a.suburb || a.neighbourhood || p.name || 'Location';
        // sub = area, city, state for context
        const area = a.suburb || a.neighbourhood || a.quarter || a.village || '';
        const city = a.city || a.town || a.county || a.state_district || '';
        const st = a.state || '';
        const sub = [area, city, st].filter(Boolean).filter((v,i,arr)=>arr.indexOf(v)===i).slice(0,3).join(', ') || 'India';
        return `<div class="search-item geo" data-lat="${p.lat}" data-lon="${p.lon}" data-name="${String(main).replace(/"/g,'')}" data-sub="${String(sub).replace(/"/g,'')}">
          <div class="si-name">📍 ${main}</div><div class="si-state">${sub}</div>
        </div>`;
      }).join('');
      if(loader) loader.outerHTML = items;
      searchResults.querySelectorAll('.search-item.geo').forEach(item => {
        item.onclick = () => selectArea(parseFloat(item.dataset.lat), parseFloat(item.dataset.lon), item.dataset.name, item.dataset.sub);
      });
    }catch(e){
      const loader = document.getElementById('searchLoading');
      if(loader) loader.outerHTML = `<div class="search-empty">Couldn't reach search — check your connection.</div>`;
    }
  }

  let areaSearchMarker = null;
  function dropRedPin(lat, lon, name){
    if(areaSearchMarker) map.removeLayer(areaSearchMarker);
    const redPin = L.divIcon({
      className:'', iconSize:[28,38], iconAnchor:[14,38],
      html:`<svg width="28" height="38" viewBox="0 0 28 38" xmlns="http://www.w3.org/2000/svg">
        <path d="M14 0C6.3 0 0 6.3 0 14c0 9.5 14 24 14 24s14-14.5 14-24C28 6.3 21.7 0 14 0z" fill="#E4573D"/>
        <circle cx="14" cy="14" r="5.5" fill="#fff"/></svg>`
    });
    areaSearchMarker = L.marker([lat, lon], {icon:redPin, zIndexOffset:1000}).addTo(map).bindTooltip(name, {direction:'top', offset:[0,-34]});
  }

  // open weather for ANY searched area (block/locality level)
  async function selectArea(lat, lon, name, sub){
    searchResults.classList.remove('show');
    searchInput.value = name;
    map.flyTo([lat, lon], 14, {duration:1.4});
    dropRedPin(lat, lon, name);

    const place = {
      id:'area_'+Math.round(lat*1000)+'_'+Math.round(lon*1000),
      code:'SEARCHED LOCATION', name:name, state:sub||'India', type:'AWS', lat:lat, lon:lon
    };
    const nearest = findNearestStation(lat, lon);
    if(nearest) place.nearest = nearest;
    try{
      const data = await fetchStationData(place);
      place.data = data;
      place.risk = computeRisk(data.hourlyRain, data.current, data.daily);
      place._liveScore = place.risk.score;
      place._liveTemp = data.current.temperature_2m;
      place._liveRain = data.current.precipitation;
      openDrawer(place);
    }catch(e){ alert('Could not load weather for ' + name); }
  }

  function selectStationById(id){
    const s = INDIA_STATIONS.find(x => x.id === id);
    if(!s) return;
    map.flyTo([s.lat, s.lon], 14, {duration: 1.4});
    dropRedPin(s.lat, s.lon, s.name);
    const entry = markers[s.id];
    if(entry && entry.station.data) openDrawer(entry.station);
    searchResults.classList.remove('show');
    searchInput.value = s.name;
  }
  const searchClear = document.getElementById('searchClear');
